window.AUTH=window.AUTH||{};window.AUTH["20-1410"]={"d":"20-1410","id":"2021/20-1410","n":"Ruan v. United States","briefs":[{"k":"petitioner","label":"Brief of petitioner Xiulu Ruan","date":"2021-12-20","url":"https://www.supremecourt.gov/DocketPDF/20/20-1410/205782/20211220153519404_Ruan%20Brief%20for%20the%20Petitioner.pdf","side":"pet","n":81},{"k":"petitioner","label":"Brief of petitioner Shakeel Kahn","date":"2021-12-20","url":"https://www.supremecourt.gov/DocketPDF/20/20-1410/207117/20211230191719068_41854%20pdf%20Brindley%20I.pdf","side":"pet","n":97},{"k":"respondent","label":"Brief of respondent United States","date":"2022-01-19","url":"https://www.supremecourt.gov/DocketPDF/20/20-1410/210722/20220119141513698_20-1410bsUnitedStates.pdf","side":"res","n":70},{"k":"reply","label":"Reply of petitioner Shakeel Kahn","date":"2022-02-17","url":"https://www.supremecourt.gov/DocketPDF/20/20-1410/214480/20220217174539797_42126%20pdf%20Brindley.pdf","side":"pet","n":32},{"k":"reply","label":"Reply of petitioner Xiulu Ruan","date":"2022-02-18","url":"https://www.supremecourt.gov/DocketPDF/20/20-1410/214493/20220218094053794_Ruan%20Merits%20Reply%20Brief.pdf","side":"pet","n":38}],"opinion":"https://www.supremecourt.gov/opinions/21pdf/597us2r60_8oka.pdf","tr":true,"items":[{"t":"case","label":"Arthur Andersen LLP v. United States","cite":"544 U.S. 696","y":2005,"id":"2004/04-368","sc":1,"sum":"The Court held that the jury instructions failed to convey that the federal document law required a \"consciousness of wrongdoing\" for conviction. There was nothing inherently corrupt in ordering employees to destroy documents, even if the aim was to keep the documents from the government.","sumSrc":"Oyez","by":{"0":"33, 37, 38"}},{"t":"case","label":"Barsky v. Board of Regents","cite":"347 U.S. 442","y":1954,"id":"scdb/1953-067","sc":1,"sum":"The New York law, on its face or as so construed and applied, does not violate the Due Process Clause of the Fourteenth Amendment. Pp. 443-456. _ (a) The decision of the highest state court that a violation of 2 U. S. C. § 192, though not a crime under New York law, was a \"crime\" within the meaning of § 6514-2 (b) of the State Education Law, is conclusive here.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"38"}},{"t":"case","label":"Bond v. United States","cite":"572 U.S. 844","y":2014,"id":"2013/12-158","sc":1,"sum":"The Court found that international treaties cannot overstep state sovereignty, and enforcement should be limited to international affairs.","sumSrc":"Oyez","by":{"0":"5, 17"}},{"t":"case","label":"Boyd v. United States","cite":"271 U.S. 104","y":1926,"id":"scdb/1925-109","sc":1,"op":1,"sum":"1. The mere fact that the quantity of morphine dispensed by a registered physician by a prescription to a morphine addict without a written order, exceeds what would be required by the patient for a single dose, does not constitute a violation of the AntiNarcotic Act. Linder v. United States, 268 U. S.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"27","1":"36","3":"14, 15"}},{"t":"case","label":"Buckman Co. v. Plaintiffs’ Legal Comm.","cite":"531 U.S. 341","y":2001,"id":"2000/98-1768","sc":1,"sum":"The Court held that the plaintiffs' state-law fraud-on-the-FDA claims conflicted with, and were therefore pre-empted by, the FDCA, as amended by the MDA. \"The conflict,\" wrote Chief Justice Rehnquist for the Court, \"stems from the fact that the federal statutory scheme amply empowers the FDA to punish and deter fraud against the Agency, and that this authority is used by the Agency to achieve a somewhat delicate balance of statutory objectives.","sumSrc":"Oyez","by":{"0":"35"}},{"t":"case","label":"Carter v. United States","cite":"530 U.S. 255","y":2000,"id":"1999/99-5716","sc":1,"op":1,"sum":"The Court held that federal bank larceny is not a \"lesser included offense\" of federal bank robbery. The \"[p]etitioner is accordingly prohibited as a matter of law from obtaining a lesser included offense instruction,\" wrote Justice Thomas for the Court.","sumSrc":"Oyez","by":{"0":"29","1":"31","2":"36"}},{"t":"case","label":"Cheek v. United States","cite":"498 U.S. 192","y":1991,"id":"1990/89-658","sc":1,"op":1,"sum":"Petitioner Cheek was charged with six counts of willfully failing to file a federal income tax return in violation of § 7203 of the Internal Revenue Code (Code) and three counts of willfully attempting to evade his income taxes in violation of §7201. Although admitting that he had not filed his returns, he testified that he had not acted willfully because he sincerely believed, based on his indoctrination by a group …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"46","1":"12, 29, 30, 32","2":"25, 34","3":"6, 12, 16"}},{"t":"case","label":"Cleveland v. United States","cite":"531 U.S. 12","y":2000,"id":"2000/99-804","sc":1,"sum":"The Court held that State and municipal licenses in general, and Louisiana's video poker licenses in particular, do not rank as \"property,\" for purposes of federal law, in the hands of the official licensor.","sumSrc":"Oyez","by":{"0":"5"}},{"t":"case","label":"Elonis v. United States","cite":"575 U.S. 723","y":2015,"id":"2014/13-983","sc":1,"op":3,"sum":"The Court found that in order to violate the transmission of threats provision, the threat requires both an objective and subjective intent.","sumSrc":"Oyez","by":{"0":"20, 29, 33, 34","1":"14, 24, 31","2":"34","4":"6"}},{"t":"case","label":"Gonzales v. Carhart","cite":"550 U.S. 124","y":2007,"id":"2006/05-380","sc":1,"sum":"The Court held that the Partial-Birth Abortion Ban Act did not violate a mother's personal liberty guaranteed under the Fifth Amendment.","sumSrc":"Oyez","by":{"0":"37"}},{"t":"case","label":"Gonzales v. Oregon","cite":"546 U.S. 243","y":2006,"id":"2005/04-623","sc":1,"op":3,"sum":"The Court decided that the Controlled Substance Act did not ban the use of controlled substances in physician-assisted suicide, nor does the Attorney General have the power to determine what is a violation of the Act.","sumSrc":"Oyez","by":{"0":"passim","1":"15, 43","2":"passim","3":"17, 18, 19","4":"23"}},{"t":"case","label":"Hawker v. New York","cite":"170 U.S. 189","y":1898,"id":"scdb/1897-113","sc":1,"sum":"The provision in the act of the legislature of New York of May 9, 1893, c. 661, relating to the public health, as amended by the act of April 25, 1895, c. 398, that “ any person who,... after conviction of a felony, shall attempt to practise medicine, or shall so practise,... shall be guilty of a misdemeanor, and on conviction thereof shall be punished by a fine of not more than two hundred and fifty dollars, or …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"38"}},{"t":"case","label":"Page(s) Jin Fuey Moy v. United States","cite":"254 U.S. 189","y":1920,"id":"scdb/1920-019","sc":1,"sum":"1. In a case properly here on a constitutional question under Jud. Code, §238, the court retains its jurisdiction to decide other quest.ons presented, after the constitutional question has been settled in another case.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"26","2":"31, 32","4":"19"}},{"t":"case","label":"Kelly v. United States","cite":"140 S. Ct. 1565","y":2020,"id":"2019/18-1059","sc":1,"sum":"The Court held that Baroni and Kelly, who executed the New Jersey “Bridgegate” political retribution scheme against Fort Lee’s mayor, did not violate the federal-program fraud or wire fraud laws because they did not aim to obtain money or property from the federal Port Authority.","sumSrc":"Oyez","by":{"0":"5"}},{"t":"case","label":"Linder v. United States","cite":"268 U.S. 5","y":1925,"id":"scdb/1924-117","sc":1,"op":2,"ar":1,"sum":"1. Any provision of an act of Congress ostensibly enacted under power granted by the Constitution, not naturally and reasonably adapted to the effective exercise of such power but solely to the achievement of something plainly within tha power reserved to the States, is invalid and can. not be enforced.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"27, 45","1":"36, 38","2":"32","3":"14, 15","4":"18, 19"}},{"t":"case","label":"Liparota v. United States","cite":"471 U.S. 419","y":1985,"id":"1984/84-5108","sc":1,"op":5,"ar":1,"sum":"Absent any indication of a contrary purpose in the statute's language or legislative history, the Government in a prosecution for violation of § 2024(b)(1) must prove that the defendant knew that his acquisition or possession of food stamps was in a manner unauthorized by statute or regulations.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"19, 21, 46","1":"20, 22","2":"34"}},{"t":"case","label":"McDonnell v. United States","cite":"136 S. Ct. 2355","y":2016,"id":"2015/15-474","sc":1,"sum":"The Court held that, for the purpose of federal bribery statutes, an “official act” is a decision or action on a question, matter, cause, suit, proceeding, or controversy that involves a specific exercise of formal governmental power.","sumSrc":"Oyez","by":{"0":"51","4":"7"}},{"t":"case","label":"Morissette v. United States","cite":"342 U.S. 246","y":1952,"id":"scdb/1951-028","sc":1,"op":3,"ar":5,"sum":"1. A criminal intent is an essential element of an offense under 18 U. S. C. § 641, which provides that \"whoever embezzles, steals, purloins, or knowingly converts\" property -of the United States is punishable by fine and imprisonment.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"passim","1":"14, 19, 21","3":"1"}},{"t":"case","label":"New York Trust Co. v. Eisner","cite":"256 U.S. 345","y":1921,"id":"scdb/1920-095","sc":1,"sum":"1. The Act of September 8, 1916, c. 463, Title II, § 201 et seq., 39 Stat. 777, imposes a tax on the transfer of the net estate of,every decedent, graduated according to the value as ascertained by deducting, in the ease of a resident, from the gross estate, funeral, administration and other expenses and charges,, and a specified exemption; the tax is due in one year from the decedent’s death, is payable primarily …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"42"}},{"t":"case","label":"NFIB v. Sebelius","cite":"567 U.S. 519","y":2012,"id":"2011/11-393","sc":1,"sum":"Cases in which the Court held that the minimum coverage requirement of the Affordable Care Act was constitutional, that Congress had the power to enforce the taxation of most Americans that did not buy the minimum level of coverage, and that the federal government exceeded its power by pressuring States into accepting conditions that Congress could not impose directly by threatening to withhold all federal funding under Medicaid.","sumSrc":"Oyez","by":{"0":"39"}},{"t":"case","label":"Rehaif v. United States","cite":"139 S. Ct. 2191","y":2019,"id":"2018/17-9560","sc":1,"op":11,"ar":4,"sum":"In a prosecution under 18 U. S. C. §922(g) and §924(a)(2), the Government must prove both that the defendant knew he possessed a firearm and that he knew he belonged to the relevant category of persons barred from possessing a firearm.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"17","1":"passim","2":"34","3":"11, 12, 18, 24","4":"15"}},{"t":"case","label":"Smith v. United States","cite":"568 U.S. 106","y":2013,"id":"2012/11-8976","sc":1,"op":3,"sum":"The Court held that the burden lies on the defendant, instead of the government, to prove withdrawal from a conspiracy regardless of when the withdrawal took place.","sumSrc":"Oyez","by":{"0":"22"}},{"t":"case","label":"Staples v. United States","cite":"511 U.S. 600","y":1994,"id":"1993/92-1441","sc":1,"op":4,"ar":1,"sum":"Noting that “a severe penalty is a further factor tending to suggest that . . . the usual presumption that a defendant must know the facts that make his conduct illegal should apply”.","sumSrc":"opinion","by":{"0":"passim","1":"19, 20, 21, 26, 31"}},{"t":"case","label":"Torres v. Lynch","cite":"578 U.S. 452","y":2016,"id":"2015/14-1096","sc":1,"sum":"The Court determined that a state offense may constitute an aggravated felony for the purpose of the removal of a permanent resident when it includes all the elements of the federal statute with the exception of the interstate commerce element.","sumSrc":"Oyez","by":{"0":"18, 21","1":"19","3":"11","4":"16"}},{"t":"case","label":"Page(s) United States v. Arny","cite":"831 F.3d 725","y":2016,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/831/725/","by":{"0":"50"}},{"t":"case","label":"United States v. Balint","cite":"258 U.S. 250","y":1922,"id":"scdb/1921-077","sc":1,"by":{"0":"27","1":"23"}},{"t":"case","label":"United States v. Burwell","cite":"690 F.3d 500","y":2012,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/690/500/","by":{"0":"18"}},{"t":"case","label":"United States v. Chube","cite":"538 F.3d 693","y":2008,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/538/693/","by":{"0":"31"}},{"t":"case","label":"United States v. Doremus","cite":"249 U.S. 86","y":1919,"id":"scdb/1918-174","sc":1,"sum":"While Congress may not exertauthority which is wholly reserved to the States, the power conferred by the Constitution to levy excise taxes, uniform throughout'the United States, is to be exercised at the discretion of-Congress; and, where the provisions of the law enacted have some reasonable relation to this power, the fact that they may have been impelled by a motive, or may accomplish a purpose, other than the …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"26","1":"23"}},{"t":"case","label":"United States v. Enmon","cite":"686 Fed. Appx. 769","y":2017,"court":"11th Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./686/769/","by":{"0":"16, 48","4":"1"}},{"t":"case","label":"United States v. Feingold","cite":"454 F.3d 1001","y":2006,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/454/1001/","by":{"0":"passim","1":"34, 35"}},{"t":"case","label":"United States v. Hooker","cite":"541 F.2d 300","y":1976,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.2d/541/300/","by":{"0":"22"}},{"t":"case","label":"United States v. Hurwitz","cite":"459 F.3d 463","y":2006,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/459/463/","by":{"0":"passim","1":"45"}},{"t":"case","label":"United States v. Joseph","cite":"709 F.3d 1082","y":2013,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/709/1082/","op":1,"by":{"0":"13","1":"15, 34, 45"}},{"t":"case","label":"United States v. Kohli","cite":"847 F.3d 483","y":2017,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/847/483/","by":{"0":"31"}},{"t":"case","label":"United States v. McIver","cite":"470 F.3d 550","y":2006,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/470/550/","by":{"0":"49","1":"15, 34"}},{"t":"case","label":"Page(s) United States v. Moore","cite":"423 U.S. 122","y":1975,"id":"1975/74-759","sc":1,"op":5,"sum":"Describing Congress' intent “to confne authorized medical practice within accepted limits” (emphasis added).","sumSrc":"opinion","by":{"0":"passim","1":"16, 18, 35, 42","2":"passim","3":"2, 10, 13","4":"3, 4"}},{"t":"case","label":"United States v. Murray","cite":"618 F.2d 892","y":1980,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/618/892/","by":{"0":"21"}},{"t":"case","label":"United States v. Outler","cite":"659 F.2d 1306","y":1981,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/659/1306/","by":{"0":"21, 22"}},{"t":"case","label":"United States v. Rosenberg","cite":"515 F.2d 190","y":1975,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/515/190/","by":{"0":"21, 32","1":"40, 41","3":"11"}},{"t":"case","label":"United States v. Sabean","cite":"885 F.3d 27","y":2018,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/885/27/","by":{"0":"31, 32, 49","1":"45"}},{"t":"case","label":"United States v. Singh","cite":"390 F.3d 168","y":2004,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/390/168/","by":{"0":"32"}},{"t":"case","label":"United States v. Smith","cite":"573 F.3d 639","y":2009,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/573/639/","by":{"0":"49","1":"45"}},{"t":"case","label":"United States v. Steele","cite":"147 F.3d 1316","y":1998,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/147/1316/","ar":1,"sum":"Holding that “the course of professional practice” “need not be negated in the indictment,” but declining to address “who bears the burden of persuasion”.","sumSrc":"brief:0","by":{"0":"22"}},{"t":"case","label":"United States v. Tobin","cite":"676 F.3d 1264","y":2012,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/676/1264/","by":{"0":"48","1":"33","4":"1"}},{"t":"case","label":"United States v. Tran Trong Cuong","cite":"18 F.3d 1132","y":1994,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/18/1132/","by":{"0":"37","1":"40, 45, 46"}},{"t":"case","label":"United States v. United States Gypsum Co.","cite":"438 U.S. 422","y":1978,"id":"1977/76-1560","sc":1,"op":3,"sum":"Several major gypsum board manufacturers and various of their officials were indicted for violations of § 1 of the Sherman Act by allegedly engaging in a price-fixing conspiracy. One of the types of actions allegedly taken in formulating and effectuating the conspiracy was interseller price verification, i. e., the practice of telephoning a competing manufacturer to determine the price being currently offered on …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"passim","4":"22"}},{"t":"case","label":"Page(s) United States v. Vamos","cite":"797 F.2d 1146","y":1986,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/797/1146/","by":{"0":"32","1":"45"}},{"t":"case","label":"United States v. Varma","cite":"691 F.2d 460","y":1982,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.2d/691/460/","by":{"0":"22"}},{"t":"case","label":"United States v. Volkman","cite":"797 F.3d 377","y":2015,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/797/377/","by":{"0":"32, 36"}},{"t":"case","label":"United States v. Voorhies","cite":"663 F.2d 30","y":1981,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/663/30/","by":{"0":"32"}},{"t":"case","label":"United States v. Wexler","cite":"522 F.3d 194","y":2008,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/522/194/","by":{"0":"32, 36","1":"45"}},{"t":"case","label":"United States v. Williams","cite":"836 F.3d 1","y":2016,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/836/1/","by":{"0":"51"}},{"t":"case","label":"United States v. X-Citement Video, Inc.","cite":"513 U.S. 64","y":1994,"id":"1994/93-723","sc":1,"op":6,"ar":2,"sum":"The Court relied on an awkward grammatical construction as it held that the term \"knowingly\" applied to the entire passage of the law. Writing for the majority, Chief Justice William Rehnquist stated that other interpretations failed to make sense since Congress obviously did not envision people accidentally mailing underage pornographic materials.","sumSrc":"Oyez","by":{"0":"17, 34","1":"passim","3":"12","4":"17"}},{"t":"case","label":"United States v. Yermian","cite":"468 U.S. 63","y":1984,"id":"1983/83-346","sc":1,"op":4,"ar":1,"sum":"The Court held that the language of the statute applied the requirement of knowledge to the act of making false statements, rather than the jurisdiction. The Court also held that there was no legislative history to support the reading that Congress intended intent to deceive the federal government to be an element of the crime.","sumSrc":"Oyez","by":{"0":"20, 21","2":"16, 24","3":"11","4":"16, 17"}},{"t":"case","label":"Webb v. United States","cite":"249 U.S. 96","y":1919,"id":"scdb/1918-175","sc":1,"op":1,"sum":"The first sentence of § 2 of the Narcotic Drug Act of December 17, 1914, c. 1,38 Stat. 785, prohibits retail sales of morphine by druggists to persons who have no physician’s prescription, who have no order blank therefor and who cannot obtain an order blank because not of the class to which such blanks are allowed to be issued under. the act. P. 99. -.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"27"}},{"t":"case","label":"Whalen v. Roe","cite":"429 U.S. 589","y":1977,"id":"1976/75-839","sc":1,"sum":"The Court held that the requirements of the Act did not on its face violate a \"constitutionally protected 'zone of privacy.'\" The Court found that the statutory scheme evidenced \"a proper concern with, and protection of, the individual's interest in privacy\" and that the \"remote possibility\" of potential abuses of data accumulation and disclosure were not sufficient to establish an invasion of any rights or liberties protected by the Fourteenth Amendment.","sumSrc":"Oyez","by":{"0":"38"}},{"t":"case","label":"Yates v. United States","cite":"574 U.S. 528","y":2015,"id":"2014/13-7451","sc":1,"sum":"The Court ruled that a “tangible item” as defined by Section 1519 of the Sarbanes-Oxley Act is one used to record or preserve information.","sumSrc":"Oyez","by":{"0":"19"}},{"t":"usc","label":"15 U.S.C. § 1","url":"https://www.law.cornell.edu/uscode/text/15/1","stext":{"head":"§1. Trusts, etc., in restraint of trade illegal; penalty","paras":[[0,"Every contract, combination in the form of trust or otherwise, or conspiracy, in restraint of trade or commerce among the several States, or with foreign nations, is declared to be illegal. Every person who shall make any contract or engage in any combination or conspiracy hereby declared to be illegal shall be deemed guilty of a felony, and, on conviction thereof, shall be punished by fine not exceeding $100,000,000 if a corporation, or, if any other person, $1,000,000, or by imprisonment not exceeding 10 years, or by both said punishments, in the discretion of the court."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§1. Trusts, etc., in restraint of trade illegal; penalty","tname":"Commerce and Trade","by":{"0":"18"}},{"t":"usc","label":"21 U.S.C. § 801","url":"https://www.law.cornell.edu/uscode/text/21/801","subs":["(1)"],"stext":{"head":"§801. Congressional findings and declarations: controlled substances","paras":[[0,"The Congress makes the following findings and declarations:"],[0,"(1) Many of the drugs included within this subchapter have a useful and legitimate medical purpose and are necessary to maintain the health and general welfare of the American people."],[0,"(2) The illegal importation, manufacture, distribution, and possession and improper use of controlled substances have a substantial and detrimental effect on the health and general welfare of the American people."],[0,"(3) A major portion of the traffic in controlled substances flows through interstate and foreign commerce. Incidents of the traffic which are not an integral part of the interstate or foreign flow, such as manufacture, local distribution, and possession, nonetheless have a substantial and direct effect upon interstate commerce because—"],[1,"(A) after manufacture, many controlled substances are transported in interstate commerce,"],[1,"(B) controlled substances distributed locally usually have been transported in interstate commerce immediately before their distribution, and"],[1,"(C) controlled substances possessed commonly flow through interstate commerce immediately prior to such possession."],[0,"(4) Local distribution and possession of controlled substances contribute to swelling the interstate traffic in such substances."],[0,"(5) Controlled substances manufactured and distributed intrastate cannot be differentiated from controlled substances manufactured and distributed interstate. Thus, it is not feasible to distinguish, in terms of controls, between controlled substances manufactured and distributed interstate and controlled substances manufactured and distributed intrastate."],[0,"(6) Federal control of the intrastate incidents of the traffic in controlled substances is essential to the effective control of the interstate incidents of such traffic."],[0,"(7) The United States is a party to the Single Convention on Narcotic Drugs, 1961, and other international conventions designed to establish effective control over international and domestic traffic in controlled substances."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/21/801?type=usc&year=mostrecent&link-type=html"},"head":"§801. Congressional findings and declarations: controlled substances","tname":"Food and Drugs","by":{"0":"22, 22","1":"15","2":"3","4":"passim"}},{"t":"usc","label":"21 U.S.C. § 822","url":"https://www.law.cornell.edu/uscode/text/21/822","subs":["(a)(1)","(a)(2)","(b)"],"stext":{"head":"§822. Persons required to register","paras":[[0,"(a) Period of registration"],[0,"(1) Every person who manufactures or distributes any controlled substance or list I chemical, or who proposes to engage in the manufacture or distribution of any controlled substance or list I chemical, shall obtain annually a registration issued by the Attorney General in accordance with the rules and regulations promulgated by him."],[0,"(2) Every person who dispenses, or who proposes to dispense, any controlled substance, shall obtain from the Attorney General a registration issued in accordance with the rules and regulations promulgated by him. The Attorney General shall, by regulation, determine the period of such registrations. In no event, however, shall such registrations be issued for less than one year nor for more than three years."],[0,"(3)(A) Except as provided in subparagraph (C), the registration of any registrant under this subchapter to manufacture, distribute, or dispense controlled substances or list I chemicals terminates if and when such registrant—"],[1,"(i) dies;"],[1,"(ii) ceases legal existence;"],[1,"(iii) discontinues business or professional practice; or"],[1,"(iv) surrenders such registration."],[0,"(B) In the case of such a registrant who ceases legal existence or discontinues business or professional practice, such registrant shall promptly notify the Attorney General in writing of such fact."],[0,"(C) No registration under this subchapter to manufacture, distribute, or dispense controlled substances or list I chemicals, and no authority conferred thereby, may be assigned or otherwise transferred except upon such conditions as the Attorney General may specify and then only pursuant to written consent. A registrant to whom a registration is assigned or transferred pursuant to the preceding sentence may not manufacture, distribute, or dispense controlled substances or list I chemicals pursuant to such registration until the Attorney General receives such written consent."],[0,"(D) In the case of a registrant under this subchapter to manufacture, distribute, or dispense controlled substances or list I chemicals desiring to discontinue business or professional practice altogether or with respect to controlled substances and list I chemicals (without assigning or transferring such business or professional practice to another entity), such registrant shall return to the Attorney General for cancellation—"],[1,"(i) the registrant's certificate of registration;"],[1,"(ii) any unexecuted order forms in the registrant's possession; and"],[1,"(iii) any other documentation that the Attorney General may require."],[0,"(b) Authorized activities"],[0,"Persons registered by the Attorney General under this subchapter to manufacture, distribute, or dispense controlled substances or list I chemicals are authorized to possess, manufacture, distribute, or dispense such substances or chemicals (including any such activity in the conduct of research) to the extent authorized by their registration and in conformity with the other provisions of this subchapter."],[0,"(c) Exceptions"],[0,"The following persons shall not be required to register and may lawfully possess any controlled substance or list I chemical under this subchapter:"],[1,"(1) An agent or employee of any registered manufacturer, distributor, or dispenser of any controlled substance or list I chemical if such agent or employee is acting in the usual course of his business or employment."],[1,"(2) A common or contract carrier or warehouseman, or an employee thereof, whose possession of the controlled substance or list I chemical is in the usual course of his business or employment."],[1,"(3) An ultimate user who possesses such substance for a purpose specified in section 802(25) 1 of this title."],[0,"(d) Waiver"],[0,"The Attorney General may, by regulation, waive the requirement for registration of certain manufacturers, distributors, or dispensers if he finds it consistent with the public health and safety."],[0,"(e) Separate registration"],[0,"(1) A separate registration shall be required at each principal place of business or professional practice where the applicant manufactures, distributes, or dispenses controlled substances or list I chemicals."],[0,"(2) Notwithstanding paragraph (1), a registrant who is a veterinarian shall not be required to have a separate registration in order to transport and dispense controlled substances in the usual course of veterinary practice at a site other than the registrant's registered principal place of business or professional practice, so long as the site of transporting and dispensing is located in a State where the veterinarian is licensed to practice veterinary medicine and is not a principal place of business or professional practice."],[0,"(3) Notwithstanding paragraph (1), a registrant that is dispensing pursuant to section 823(g) 1 of this title narcotic drugs to individuals for maintenance treatment or detoxification treatment shall not be required to have a separate registration to incorporate one or more mobile medication units into the registrant's practice to dispense such narcotics at locations other than the registrant's principal place of business or professional practice described in paragraph (1), so long as the registrant meets such standards for operation of a mobile medication unit as the Attorney General may establish."],[0,"(f) Inspection"],[0,"The Attorney General is authorized to inspect the establishment of a registrant or applicant for registration in accordance with the rules and regulations promulgated by him."],[0,"(g) Delivery of controlled substances by ultimate users for disposal"],[0,"(1) An ultimate user who has lawfully obtained a controlled substance in accordance with this subchapter may, without being registered, deliver the controlled substance to another person for the purpose of disposal of the controlled substance if—"],[1,"(A) the person receiving the controlled substance is authorized under this subchapter to engage in such activity; and"],[1,"(B) the disposal takes place in accordance with regulations issued by the Attorney General to prevent diversion of controlled substances."],[0,"(2) In developing regulations under this subsection, the Attorney General shall take into consideration the public health and safety, as well as the ease and cost of program implementation and participation by various communities. Such regulations may not require any entity to establish or operate a delivery or disposal program."],[0,"(3) The Attorney General may, by regulation, authorize long-term care facilities, as defined by the Attorney General by regulation, to dispose of controlled substances on behalf of ultimate users who reside, or have resided, at such long-term care facilities in a manner that the Attorney General determines will provide effective controls against diversion and be consistent with the public health and safety."],[0,"(4) If a person dies while lawfully in possession of a controlled substance for personal use, any person lawfully entitled to dispose of the decedent's property may deliver the controlled substance to another person for the purpose of disposal under the same conditions as provided in paragraph (1) for an ultimate user."],[0,"(5)(A) In the case of a person receiving hospice care, an employee of a qualified hospice program, acting within the scope of employment, may handle, without being registered under this section, any controlled substance that was lawfully dispensed to the person receiving hospice care, for the purpose of disposal of the controlled substance so long as such disposal occurs onsite in accordance with all applicable Federal, State, Tribal, and local law and—"],[1,"(i) the disposal occurs after the death of a person receiving hospice care;"],[1,"(ii) the controlled substance is expired; or"],[1,"(iii)(I) the employee is—"],[2,"(aa) the physician of the person receiving hospice care; and"],[2,"(bb) registered under section 823(g) of this title; and"],[1,"(II) the hospice patient no longer requires the controlled substance because the plan of care of the hospice patient has been modified."],[0,"(B) For the purposes of this paragraph:"],[1,"(i) The terms \"hospice care\" and \"hospice program\" have the meanings given to those terms in section 1395x(dd) of title 42."],[1,"(ii) The term \"employee of a qualified hospice program\" means a physician, physician assistant, nurse, or other person who—"],[2,"(I) is employed by, or pursuant to arrangements made by, a qualified hospice program;"],[2,"(II)(aa) is licensed to perform medical or nursing services by the jurisdiction in which the person receiving hospice care was located; and"],[2,"(bb) is acting within the scope of such employment in accordance with applicable State law; and"],[2,"(III) has completed training through the qualified hospice program regarding the disposal of controlled substances in a secure and responsible manner so as to discourage abuse, misuse, or diversion."],[1,"(iii) The term \"qualified hospice program\" means a hospice program that—"],[2,"(I) has written policies and procedures for assisting in the disposal of the controlled substances of a person receiving hospice care after the person's death;"],[2,"(II) at the time when the controlled substances are first ordered—"],[3,"(aa) provides a copy of the written policies and procedures to the patient or patient representative and family;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/21/822?type=usc&year=mostrecent&link-type=html"},"head":"§822. Persons required to register","tname":"Food and Drugs","by":{"0":"4, 4, 20, 25","1":"16, 16","2":"43, 43, 43"}},{"t":"usc","label":"21 U.S.C. § 823","url":"https://www.law.cornell.edu/uscode/text/21/823","subs":["(b)","(e)","(g)(2)(H)(i)","(g)(2)(E)(i)"],"stext":{"head":"§823. Registration requirements","paras":[[0,"(a) Manufacturers of controlled substances in schedule I or II"],[0,"The Attorney General shall register an applicant to manufacture controlled substances in schedule I or II if he determines that such registration is consistent with the public interest and with United States obligations under international treaties, conventions, or protocols in effect on May 1, 1971. In determining the public interest, the following factors shall be considered:"],[1,"(1) maintenance of effective controls against diversion of particular controlled substances and any controlled substance in schedule I or II compounded therefrom into other than legitimate medical, scientific, research, or industrial channels, by limiting the importation and bulk manufacture of such controlled substances to a number of establishments which can produce an adequate and uninterrupted supply of these substances under adequately competitive conditions for legitimate medical, scientific, research, and industrial purposes;"],[1,"(2) compliance with applicable State and local law;"],[1,"(3) promotion of technical advances in the art of manufacturing these substances and the development of new substances;"],[1,"(4) prior conviction record of applicant under Federal and State laws relating to the manufacture, distribution, or dispensing of such substances;"],[1,"(5) past experience in the manufacture of controlled substances, and the existence in the establishment of effective control against diversion; and"],[1,"(6) such other factors as may be relevant to and consistent with the public health and safety."],[0,"(b) Distributors of controlled substances in schedule I or II"],[0,"The Attorney General shall register an applicant to distribute a controlled substance in schedule I or II unless he determines that the issuance of such registration is inconsistent with the public interest. In determining the public interest, the following factors shall be considered:"],[1,"(1) maintenance of effective control against diversion of particular controlled substances into other than legitimate medical, scientific, and industrial channels;"],[1,"(2) compliance with applicable State and local law;"],[1,"(3) prior conviction record of applicant under Federal or State laws relating to the manufacture, distribution, or dispensing of such substances;"],[1,"(4) past experience in the distribution of controlled substances; and"],[1,"(5) such other factors as may be relevant to and consistent with the public health and safety."],[0,"(c) Manufacturers of marijuana for research purposes"],[0,"(1)(A) As it relates to applications to manufacture marijuana for research purposes, when the Attorney General places a notice in the Federal Register to increase the number of entities registered under this chapter to manufacture marijuana to supply appropriately registered researchers in the United States, the Attorney General shall, not later than 60 days after the date on which the Attorney General receives a completed application—"],[1,"(i) approve the application; or"],[1,"(ii) request supplemental information."],[0,"(B) For purposes of subparagraph (A), an application shall be deemed complete when the applicant has submitted documentation showing each of the following:"],[1,"(i) The requirements designated in the notice in the Federal Register are satisfied."],[1,"(ii) The requirements under this chapter are satisfied."],[1,"(iii) The applicant will limit the transfer and sale of any marijuana manufactured under this subsection—"],[2,"(I) to researchers who are registered under this chapter to conduct research with controlled substances in schedule I; and"],[2,"(II) for purposes of use in preclinical research or in a clinical investigation pursuant to an investigational new drug exemption under 355(i) 1 of this title."],[1,"(iv) The applicant will transfer or sell any marijuana manufactured under this subsection only with prior, written consent for the transfer or sale by the Attorney General."],[1,"(v) The applicant has completed the application and review process under subsection (a) for the bulk manufacture of controlled substances in schedule I."],[1,"(vi) The applicant has established and begun operation of a process for storage and handling of controlled substances in schedule I, including for inventory control and monitoring security in accordance with section 105 of the Medical Marijuana and Cannabidiol Research Expansion Act."],[1,"(vii) The applicant is licensed by each State in which the applicant will conduct operations under this subsection, to manufacture marijuana, if that State requires such a license."],[0,"(C) Not later than 30 days after the date on which the Attorney General receives supplemental information requested under subparagraph (A)(ii) with respect to an application, the Attorney General shall approve or deny the application."],[0,"(2) If an application described in this subsection is denied, the Attorney General shall provide a written explanation of the basis of denial to the applicant."],[0,"(d) Limits of authorized activities"],[0,"Registration granted under subsections (a) and (b) of this section shall not entitle a registrant to (1) manufacture or distribute controlled substances in schedule I or II other than those specified in the registration, or (2) manufacture any quantity of those controlled substances in excess of the quota assigned pursuant to section 826 of this title."],[0,"(e) Manufacturers of controlled substances in schedule III, IV, or V"],[0,"The Attorney General shall register an applicant to manufacture controlled substances in schedule III, IV, or V, unless he determines that the issuance of such registration is inconsistent with the public interest. In determining the public interest, the following factors shall be considered:"],[1,"(1) maintenance of effective controls against diversion of particular controlled substances and any controlled substance in schedule III, IV, or V compounded therefrom into other than legitimate medical, scientific, or industrial channels;"],[1,"(2) compliance with applicable State and local law;"],[1,"(3) promotion of technical advances in the art of manufacturing these substances and the development of new substances;"],[1,"(4) prior conviction record of applicant under Federal or State laws relating to the manufacture, distribution, or dispensing of such substances;"],[1,"(5) past experience in the manufacture, distribution, and dispensing of controlled substances, and the existence in the establishment of effective controls against diversion; and"],[1,"(6) such other factors as may be relevant to and consistent with the public health and safety."],[0,"(f) Distributors of controlled substances in schedule III, IV, or V"],[0,"The Attorney General shall register an applicant to distribute controlled substances in schedule III, IV, or V, unless he determines that the issuance of such registration is inconsistent with the public interest. In determining the public interest, the following factors shall be considered:"],[1,"(1) maintenance of effective controls against diversion of particular controlled substances into other than legitimate medical, scientific, and industrial channels;"],[1,"(2) compliance with applicable State and local law;"],[1,"(3) prior conviction record of applicant under Federal or State laws relating to the manufacture, distribution, or dispensing of such substances;"],[1,"(4) past experience in the distribution of controlled substances; and"],[1,"(5) such other factors as may be relevant to and consistent with the public health and safety."],[0,"(g) Research by practitioners; pharmacies; research applications; construction of Article 7 of the Convention on Psychotropic Substances"],[0,"(1) The Attorney General shall register practitioners (including pharmacies, as distinguished from pharmacists) to dispense, or conduct research with, controlled substances in schedule II, III, IV, or V and shall modify the registrations of pharmacies so registered to authorize them to dispense controlled substances by means of the Internet, if the applicant is authorized to dispense, or conduct research with respect to, controlled substances under the laws of the State in which he practices. The Attorney General may deny an application for such registration or such modification of registration if the Attorney General determines that the issuance of such registration or modification would be inconsistent with the public interest. In determining the public interest, the following factors shall be considered:"],[1,"(A) The recommendation of the appropriate State licensing board or professional disciplinary authority."],[1,"(B) The applicant's experience in dispensing, or conducting research with respect to controlled substances."],[1,"(C) The applicant's conviction record under Federal or State laws relating to the manufacture, distribution, or dispensing of controlled substances."],[1,"(D) Compliance with applicable State, Federal, or local laws relating to controlled substances."],[1,"(E) Such other conduct which may threaten the public health and safety."],[0,"Separate registration under this part for practitioners engaging in research with controlled substances in schedule II, III, IV, or V, who are already registered under this part in another capacity, shall not be required."],[0,"(2)(A) Registration applications by practitioners wishing to conduct research with controlled substances in schedule I shall be referred to the Secretary, who shall determine the qualifications and competency of each practitioner requesting registration, as well as the merits of the research protocol. The Secretary, in determining the merits of each research protocol, shall consult with the Attorney General as to effective procedures to adequately safeguard against diversion of such controlled substances from legitimate medical or scientific use. Registration for the purpose of bona fide research with controlled substances in schedule I by a practitioner deemed qualified by the Secretary may be denied by the Attorney General only on a ground specified in section 824(a) of this title."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/21/823?type=usc&year=mostrecent&link-type=html"},"head":"§823. Registration requirements","tname":"Food and Drugs","by":{"0":"24, 24, 25","1":"16, 44, 28","2":"43, 43","3":"17"}},{"t":"usc","label":"21 U.S.C. § 829","url":"https://www.law.cornell.edu/uscode/text/21/829","subs":["(a)","(c)","(e)(2)(A)"],"stext":{"head":"§829. Prescriptions","paras":[[0,"(a) Schedule II substances"],[0,"Except when dispensed directly by a practitioner, other than a pharmacist, to an ultimate user, no controlled substance in schedule II, which is a prescription drug as determined under the Federal Food, Drug, and Cosmetic Act [21 U.S.C. 301 et seq.], may be dispensed without the written prescription of a practitioner, except that in emergency situations, as prescribed by the Secretary by regulation after consultation with the Attorney General, such drug may be dispensed upon oral prescription in accordance with section 503(b) of that Act [21 U.S.C. 353(b)]. Prescriptions shall be retained in conformity with the requirements of section 827 of this title. No prescription for a controlled substance in schedule II may be refilled."],[0,"(b) Schedule III and IV substances"],[0,"Except when dispensed directly by a practitioner, other than a pharmacist, to an ultimate user, no controlled substance in schedule III or IV, which is a prescription drug as determined under the Federal Food, Drug, and Cosmetic Act [21 U.S.C. 301 et seq.], may be dispensed without a written or oral prescription in conformity with section 503(b) of that Act [21 U.S.C. 353(b)]. Such prescriptions may not be filled or refilled more than six months after the date thereof or be refilled more than five times after the date of the prescription unless renewed by the practitioner."],[0,"(c) Schedule V substances"],[0,"No controlled substance in schedule V which is a drug may be distributed or dispensed other than for a medical purpose."],[0,"(d) Non-prescription drugs with abuse potential"],[0,"Whenever it appears to the Attorney General that a drug not considered to be a prescription drug under the Federal Food, Drug, and Cosmetic Act [21 U.S.C. 301 et seq.] should be so considered because of its abuse potential, he shall so advise the Secretary and furnish to him all available data relevant thereto."],[0,"(e) Controlled substances dispensed by means of the Internet"],[0,"(1) No controlled substance that is a prescription drug as determined under the Federal Food, Drug, and Cosmetic Act [21 U.S.C. 301 et seq.] may be delivered, distributed, or dispensed by means of the Internet without a valid prescription."],[0,"(2) As used in this subsection:"],[1,"(A) The term \"valid prescription\" means a prescription that is issued for a legitimate medical purpose in the usual course of professional practice by—"],[2,"(i) a practitioner who has conducted at least 1 in-person medical evaluation of the patient; or"],[2,"(ii) a covering practitioner."],[1,"(B)(i) The term \"in-person medical evaluation\" means a medical evaluation that is conducted with the patient in the physical presence of the practitioner, without regard to whether portions of the evaluation are conducted by other health professionals."],[1,"(ii) Nothing in clause (i) shall be construed to imply that 1 in-person medical evaluation demonstrates that a prescription has been issued for a legitimate medical purpose within the usual course of professional practice."],[1,"(C) The term \"covering practitioner\" means, with respect to a patient, a practitioner who conducts a medical evaluation (other than an in-person medical evaluation) at the request of a practitioner who—"],[2,"(i) has conducted at least 1 in-person medical evaluation of the patient or an evaluation of the patient through the practice of telemedicine, within the previous 24 months; and"],[2,"(ii) is temporarily unavailable to conduct the evaluation of the patient."],[0,"(3) Nothing in this subsection shall apply to—"],[1,"(A) the delivery, distribution, or dispensing of a controlled substance by a practitioner engaged in the practice of telemedicine; or"],[1,"(B) the dispensing or selling of a controlled substance pursuant to practices as determined by the Attorney General by regulation, which shall be consistent with effective controls against diversion."],[0,"(f) Partial fills of schedule II controlled substances"],[0,"(1) Partial fills"],[1,"A prescription for a controlled substance in schedule II may be partially filled if—"],[2,"(A) it is not prohibited by State law;"],[2,"(B) the prescription is written and filled in accordance with this subchapter, regulations prescribed by the Attorney General, and State law;"],[2,"(C) the partial fill is requested by the patient or the practitioner that wrote the prescription; and"],[2,"(D) the total quantity dispensed in all partial fillings does not exceed the total quantity prescribed."],[0,"(2) Remaining portions"],[0,"(A) In general"],[2,"Except as provided in subparagraph (B), remaining portions of a partially filled prescription for a controlled substance in schedule II—"],[3,"(i) may be filled; and"],[3,"(ii) shall be filled not later than 30 days after the date on which the prescription is written."],[0,"(B) Emergency situations"],[2,"In emergency situations, as described in subsection (a), the remaining portions of a partially filled prescription for a controlled substance in schedule II—"],[3,"(i) may be filled; and"],[3,"(ii) shall be filled not later than 72 hours after the prescription is issued."],[0,"(3) Currently lawful partial fills"],[1,"Notwithstanding paragraph (1) or (2), in any circumstance in which, as of the day before July 22, 2016, a prescription for a controlled substance in schedule II may be lawfully partially filled, the Attorney General may allow such a prescription to be partially filled."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/21/829?type=usc&year=mostrecent&link-type=html"},"head":"§829. Prescriptions","tname":"Food and Drugs","by":{"0":"22, 22, 22","1":"2","2":"21, 21"}},{"t":"usc","label":"21 U.S.C. § 830","url":"https://www.law.cornell.edu/uscode/text/21/830","subs":["(b)(3)(A)(ii)"],"stext":{"head":"§830. Regulation of listed chemicals and certain machines","paras":[[0,"(a) Record of regulated transactions"],[0,"(1) Each regulated person who engages in a regulated transaction involving a listed chemical, a tableting machine, or an encapsulating machine shall keep a record of the transaction for two years after the date of the transaction."],[0,"(2) A record under this subsection shall be retrievable and shall include the date of the regulated transaction, the identity of each party to the regulated transaction, a statement of the quantity and form of the listed chemical, a description of the tableting machine or encapsulating machine, and a description of the method of transfer. Such record shall be available for inspection and copying by the Attorney General."],[0,"(3) It is the duty of each regulated person who engages in a regulated transaction to identify each other party to the transaction. It is the duty of such other party to present proof of identity to the regulated person. The Attorney General shall specify by regulation the types of documents and other evidence that constitute proof of identity for purposes of this paragraph."],[0,"(b) Reports to Attorney General"],[0,"(1) Each regulated person shall report to the Attorney General, in such form and manner as the Attorney General shall prescribe by regulation—"],[1,"(A) any regulated transaction involving an extraordinary quantity of a listed chemical, an uncommon method of payment or delivery, or any other circumstance that the regulated person believes may indicate that the listed chemical will be used in violation of this subchapter;"],[1,"(B) any proposed regulated transaction with a person whose description or other identifying characteristic the Attorney General furnishes in advance to the regulated person;"],[1,"(C) any unusual or excessive loss or disappearance of a listed chemical under the control of the regulated person; and"],[1,"(D) any regulated transaction in a tableting machine or an encapsulating machine."],[0,"Each report under subparagraph (A) shall be made at the earliest practicable opportunity after the regulated person becomes aware of the circumstance involved. A regulated person may not complete a transaction with a person whose description or identifying characteristic is furnished to the regulated person under subparagraph (B) unless the transaction is approved by the Attorney General. The Attorney General shall make available to regulated persons guidance documents describing transactions and circumstances for which reports are required under subparagraph (A) and subparagraph (C)."],[0,"(2) A regulated person that manufactures a listed chemical shall report annually to the Attorney General, in such form and manner and containing such specific data as the Attorney General shall prescribe by regulation, information concerning listed chemicals manufactured by the person. The requirement of the preceding sentence shall not apply to the manufacture of a drug product that is exempted under section 802(39)(A)(iv) of this title."],[0,"(3) Mail order reporting.—(A) As used in this paragraph:"],[1,"(i) The term \"drug product\" means an active ingredient in dosage form that has been approved or otherwise may be lawfully marketed under the Food, Drug, and Cosmetic Act 1 [21 U.S.C. 301 et seq.] for distribution in the United States."],[1,"(ii) The term \"valid prescription\" means a prescription which is issued for a legitimate medical purpose by an individual practitioner licensed by law to administer and prescribe the drugs concerned and acting in the usual course of the practitioner's professional practice."],[0,"(B) Each regulated person who engages in a transaction with a nonregulated person or who engages in an export transaction which—"],[1,"(i) involves ephedrine, pseudoephedrine, or phenylpropanolamine (including drug products containing these chemicals); and"],[1,"(ii) uses or attempts to use the Postal Service or any private or commercial carrier;"],[0,"shall, on a monthly basis, submit a report of each such transaction conducted during the previous month to the Attorney General in such form, containing such data, and at such times as the Attorney General shall establish by regulation."],[0,"(C) The data required for such reports shall include—"],[1,"(i) the name of the purchaser;"],[1,"(ii) the quantity and form of the ephedrine, pseudoephedrine, or phenylpropanolamine purchased; and"],[1,"(iii) the address to which such ephedrine, pseudoephedrine, or phenylpropanolamine was sent."],[0,"(D) Except as provided in subparagraph (E), the following distributions to a nonregulated person, and the following export transactions, shall not be subject to the reporting requirement in subparagraph (B):"],[1,"(i) Distributions of sample packages of drug products when such packages contain not more than two solid dosage units or the equivalent of two dosage units in liquid form, not to exceed 10 milliliters of liquid per package, and not more than one package is distributed to an individual or residential address in any 30-day period."],[1,"(ii) Distributions of drug products by retail distributors that may not include face-to-face transactions to the extent that such distributions are consistent with the activities authorized for a retail distributor as specified in section 802(49) of this title, except that this clause does not apply to sales of scheduled listed chemical products at retail."],[1,"(iii) Distributions of drug products to a resident of a long term care facility (as that term is defined in regulations prescribed by the Attorney General) or distributions of drug products to a long term care facility for dispensing to or for use by a resident of that facility."],[1,"(iv) Distributions of drug products pursuant to a valid prescription."],[1,"(v) Exports which have been reported to the Attorney General pursuant to section 954 or 971 of this title or which are subject to a waiver granted under section 971(f)(2) of this title."],[1,"(vi) Any quantity, method, or type of distribution or any quantity, method, or type of distribution of a specific listed chemical (including specific formulations or drug products) or of a group of listed chemicals (including specific formulations or drug products) which the Attorney General has excluded by regulation from such reporting requirement on the basis that such reporting is not necessary for the enforcement of this subchapter or subchapter II."],[0,"(E) The Attorney General may revoke any or all of the exemptions listed in subparagraph (D) for an individual regulated person if he finds that drug products distributed by the regulated person are being used in violation of this subchapter or subchapter II. The regulated person shall be notified of the revocation, which will be effective upon receipt by the person of such notice, as provided in section 971(c)(1) of this title, and shall have the right to an expedited hearing as provided in section 971(c)(2) of this title."],[0,"(c) Confidentiality of information obtained by Attorney General; non-disclosure; exceptions"],[0,"(1) Except as provided in paragraph (2), any information obtained by the Attorney General under this section which is exempt from disclosure under section 552(a) of title 5, by reason of section 552(b)(4) of such title, is confidential and may not be disclosed to any person."],[0,"(2) Information referred to in paragraph (1) may be disclosed only—"],[1,"(A) to an officer or employee of the United States engaged in carrying out this subchapter, subchapter II, or the customs laws;"],[1,"(B) when relevant in any investigation or proceeding for the enforcement of this subchapter, subchapter II, or the customs laws;"],[1,"(C) when necessary to comply with an obligation of the United States under a treaty or other international agreement; or"],[1,"(D) to a State or local official or employee in conjunction with the enforcement of controlled substances laws or chemical control laws."],[0,"(3) The Attorney General shall—"],[1,"(A) take such action as may be necessary to prevent unauthorized disclosure of information by any person to whom such information is disclosed under paragraph (2); and"],[1,"(B) issue guidelines that limit, to the maximum extent feasible, the disclosure of proprietary business information, including the names or identities of United States exporters of listed chemicals, to any person to whom such information is disclosed under paragraph (2)."],[0,"(4) Any person who is aggrieved by a disclosure of information in violation of this section may bring a civil action against the violator for appropriate relief."],[0,"(5) Notwithstanding paragraph (4), a civil action may not be brought under such paragraph against investigative or law enforcement personnel of the Drug Enforcement Administration."],[0,"(d) Scheduled listed chemicals; restrictions on sales quantity; requirements regarding nonliquid forms"],[0,"With respect to ephedrine base, pseudoephedrine base, or phenylpropanolamine base in a scheduled listed chemical product—"],[1,"(1) the quantity of such base sold at retail in such a product by a regulated seller, or a distributor required to submit reports by subsection (b)(3) may not, for any purchaser, exceed a daily amount of 3.6 grams, without regard to the number of transactions; and"],[1,"(2) such a seller or distributor may not sell such a product in nonliquid form (including gel caps) at retail unless the product is packaged in blister packs, each blister containing not more than 2 dosage units, or where the use of blister packs is technically infeasible, the product is packaged in unit dose packets or pouches."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/21/830?type=usc&year=mostrecent&link-type=html"},"head":"§830. Regulation of listed chemicals and certain machines","tname":"Food and Drugs","by":{"0":"22","2":"21"}},{"t":"usc","label":"21 U.S.C. § 841","url":"https://www.law.cornell.edu/uscode/text/21/841","subs":["(a)(1)","(b)(1)(C)","(a)","(b)(2)"],"stext":{"head":"§841. Prohibited acts A","paras":[[0,"(a) Unlawful acts"],[0,"Except as authorized by this subchapter, it shall be unlawful for any person knowingly or intentionally—"],[1,"(1) to manufacture, distribute, or dispense, or possess with intent to manufacture, distribute, or dispense, a controlled substance; or"],[1,"(2) to create, distribute, or dispense, or possess with intent to distribute or dispense, a counterfeit substance."],[0,"(b) Penalties"],[0,"Except as otherwise provided in section 849, 859, 860, or 861 of this title, any person who violates subsection (a) of this section shall be sentenced as follows:"],[0,"(1)(A) In the case of a violation of subsection (a) of this section involving—"],[1,"(i) 1 kilogram or more of a mixture or substance containing a detectable amount of heroin;"],[1,"(ii) 5 kilograms or more of a mixture or substance containing a detectable amount of—"],[2,"(I) coca leaves, except coca leaves and extracts of coca leaves from which cocaine, ecgonine, and derivatives of ecgonine or their salts have been removed;"],[2,"(II) cocaine, its salts, optical and geometric isomers, and salts of isomers;"],[2,"(III) ecgonine, its derivatives, their salts, isomers, and salts of isomers; or"],[2,"(IV) any compound, mixture, or preparation which contains any quantity of any of the substances referred to in subclauses (I) through (III);"],[1,"(iii) 280 grams or more of a mixture or substance described in clause (ii) which contains cocaine base;"],[1,"(iv) 100 grams or more of phencyclidine (PCP) or 1 kilogram or more of a mixture or substance containing a detectable amount of phencyclidine (PCP);"],[1,"(v) 10 grams or more of a mixture or substance containing a detectable amount of lysergic acid diethylamide (LSD);"],[1,"(vi) 400 grams or more of a mixture or substance containing a detectable amount of N-phenyl-N- [ 1- ( 2-phenylethyl ) -4-piperidinyl ] propanamide or 100 grams or more of a mixture or substance containing a detectable amount of any analogue of N-phenyl-N-[1-(2-phenylethyl)-4-piperidinyl] propanamide;"],[1,"(vii) 1000 kilograms or more of a mixture or substance containing a detectable amount of marihuana, or 1,000 or more marihuana plants regardless of weight; or"],[1,"(viii) 50 grams or more of methamphetamine, its salts, isomers, and salts of its isomers or 500 grams or more of a mixture or substance containing a detectable amount of methamphetamine, its salts, isomers, or salts of its isomers;"],[0,"such person shall be sentenced to a term of imprisonment which may not be less than 10 years or more than life and if death or serious bodily injury results from the use of such substance shall be not less than 20 years or more than life, a fine not to exceed the greater of that authorized in accordance with the provisions of title 18 or $10,000,000 if the defendant is an individual or $50,000,000 if the defendant is other than an individual, or both. If any person commits such a violation after a prior conviction for a serious drug felony or serious violent felony has become final, such person shall be sentenced to a term of imprisonment of not less than 15 years and not more than life imprisonment and if death or serious bodily injury results from the use of such substance shall be sentenced to life imprisonment, a fine not to exceed the greater of twice that authorized in accordance with the provisions of title 18 or $20,000,000 if the defendant is an individual or $75,000,000 if the defendant is other than an individual, or both. If any person commits a violation of this subparagraph or of section 849, 859, 860, or 861 of this title after 2 or more prior convictions for a serious drug felony or serious violent felony have become final, such person shall be sentenced to a term of imprisonment of not less than 25 years and fined in accordance with the preceding sentence. Notwithstanding section 3583 of title 18, any sentence under this subparagraph shall, in the absence of such a prior conviction, impose a term of supervised release of at least 5 years in addition to such term of imprisonment and shall, if there was such a prior conviction, impose a term of supervised release of at least 10 years in addition to such term of imprisonment. Notwithstanding any other provision of law, the court shall not place on probation or suspend the sentence of any person sentenced under this subparagraph. No person sentenced under this subparagraph shall be eligible for parole during the term of imprisonment imposed therein."],[0,"(B) In the case of a violation of subsection (a) of this section involving—"],[1,"(i) 100 grams or more of a mixture or substance containing a detectable amount of heroin;"],[1,"(ii) 500 grams or more of a mixture or substance containing a detectable amount of—"],[2,"(I) coca leaves, except coca leaves and extracts of coca leaves from which cocaine, ecgonine, and derivatives of ecgonine or their salts have been removed;"],[2,"(II) cocaine, its salts, optical and geometric isomers, and salts of isomers;"],[2,"(III) ecgonine, its derivatives, their salts, isomers, and salts of isomers; or"],[2,"(IV) any compound, mixture, or preparation which contains any quantity of any of the substances referred to in subclauses (I) through (III);"],[1,"(iii) 28 grams or more of a mixture or substance described in clause (ii) which contains cocaine base;"],[1,"(iv) 10 grams or more of phencyclidine (PCP) or 100 grams or more of a mixture or substance containing a detectable amount of phencyclidine (PCP);"],[1,"(v) 1 gram or more of a mixture or substance containing a detectable amount of lysergic acid diethylamide (LSD);"],[1,"(vi) 40 grams or more of a mixture or substance containing a detectable amount of N-phenyl-N- [ 1- ( 2-phenylethyl ) -4-piperidinyl ] propanamide or 10 grams or more of a mixture or substance containing a detectable amount of any analogue of N-phenyl-N-[1-(2-phenylethyl)-4-piperidinyl] propanamide;"],[1,"(vii) 100 kilograms or more of a mixture or substance containing a detectable amount of marihuana, or 100 or more marihuana plants regardless of weight; or"],[1,"(viii) 5 grams or more of methamphetamine, its salts, isomers, and salts of its isomers or 50 grams or more of a mixture or substance containing a detectable amount of methamphetamine, its salts, isomers, or salts of its isomers;"],[0,"such person shall be sentenced to a term of imprisonment which may not be less than 5 years and not more than 40 years and if death or serious bodily injury results from the use of such substance shall be not less than 20 years or more than life, a fine not to exceed the greater of that authorized in accordance with the provisions of title 18 or $5,000,000 if the defendant is an individual or $25,000,000 if the defendant is other than an individual, or both. If any person commits such a violation after a prior conviction for a serious drug felony or serious violent felony has become final, such person shall be sentenced to a term of imprisonment which may not be less than 10 years and not more than life imprisonment and if death or serious bodily injury results from the use of such substance shall be sentenced to life imprisonment, a fine not to exceed the greater of twice that authorized in accordance with the provisions of title 18 or $8,000,000 if the defendant is an individual or $50,000,000 if the defendant is other than an individual, or both. Notwithstanding section 3583 of title 18, any sentence imposed under this subparagraph shall, in the absence of such a prior conviction, include a term of supervised release of at least 4 years in addition to such term of imprisonment and shall, if there was such a prior conviction, include a term of supervised release of at least 8 years in addition to such term of imprisonment. Notwithstanding any other provision of law, the court shall not place on probation or suspend the sentence of any person sentenced under this subparagraph. No person sentenced under this subparagraph shall be eligible for parole during the term of imprisonment imposed therein."],[0,"(C) In the case of a controlled substance in schedule I or II, gamma hydroxybutyric acid (including when scheduled as an approved drug product for purposes of section 3(a)(1)(B) of the Hillory J. Farias and Samantha Reid Date-Rape Drug Prohibition Act of 2000), or 1 gram of flunitrazepam, except as provided in subparagraphs (A), (B), and (D), such person shall be sentenced to a term of imprisonment of not more than 20 years and if death or serious bodily injury results from the use of such substance shall be sentenced to a term of imprisonment of not less than twenty years or more than life, a fine not to exceed the greater of that authorized in accordance with the provisions of title 18 or $1,000,000 if the defendant is an individual or $5,000,000 if the defendant is other than an individual, or both. If any person commits such a violation after a prior conviction for a felony drug offense has become final, such person shall be sentenced to a term of imprisonment of not more than 30 years and if death or serious bodily injury results from the use of such substance shall be sentenced to life imprisonment, a fine not to exceed the greater of twice that authorized in accordance with the provisions of title 18 or $2,000,000 if the defendant is an individual or $10,000,000 if the defendant is other than an individual, or both. Notwithstanding section 3583 of title 18, any sentence imposing a term of imprisonment under this paragraph shall, in the absence of such a prior conviction, impose a term of supervised release of at least 3 years in addition to such term of imprisonment and shall, if there was such a prior conviction, impose a term of supervised release of at least 6 years in addition to such term of imprisonment. Notwithstanding any other provision of law, the court shall not place on probation or suspend the sentence of any person sentenced under the provisions of this subparagraph which provide for a mandatory term of imprisonment if death or serious bodily injury results, nor shall a person so sentenced be eligible for parole during the term of such a sentence."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/21/841?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§841. Prohibited acts A","tname":"Food and Drugs","by":{"0":"passim, 24","1":"passim, 16, 35, 2, 24","2":"27, 28, 30, 33, 38, 42, 3, 12, 3, 12, 3, 12, 3, 12","4":"passim"}},{"t":"usc","label":"21 U.S.C. § 842","url":"https://www.law.cornell.edu/uscode/text/21/842","subs":["(a)(2)","(a)(12)(B)","(c)(1)(A)","(c)(2)(A)","(2)","(11)","(a)(17)","(c)(2)(D)"],"stext":{"head":"§842. Prohibited acts B","paras":[[0,"(a) Unlawful acts"],[0,"It shall be unlawful for any person—"],[1,"(1) who is subject to the requirements of part C to distribute or dispense a controlled substance in violation of section 829 of this title;"],[1,"(2) who is a registrant to distribute or dispense a controlled substance not authorized by his registration to another registrant or other authorized person or to manufacture a controlled substance not authorized by his registration;"],[1,"(3) who is a registrant to distribute a controlled substance in violation of section 825 of this title;"],[1,"(4) to remove, alter, or obliterate a symbol or label required by section 825 of this title;"],[1,"(5) to refuse or negligently fail to make, keep, or furnish any record, report, notification, declaration, order or order form, statement, invoice, or information required under this subchapter or subchapter II;"],[1,"(6) to refuse any entry into any premises or inspection authorized by this subchapter or subchapter II;"],[1,"(7) to remove, break, injure, or deface a seal placed upon controlled substances pursuant to section 824(f) or 881 of this title or to remove or dispose of substances so placed under seal;"],[1,"(8) to use, to his own advantage, or to reveal, other than to duly authorized officers or employees of the United States, or to the courts when relevant in any judicial proceeding under this subchapter or subchapter II, any information acquired in the course of an inspection authorized by this subchapter concerning any method or process which as a trade secret is entitled to protection, or to use to his own advantage or reveal (other than as authorized by section 830 of this title) any information that is confidential under such section;"],[1,"(9) who is a regulated person to engage in a regulated transaction without obtaining the identification required by 830(a)(3) of this title.1"],[1,"(10) negligently to fail to keep a record or make a report under section 830 of this title or negligently to fail to self-certify as required under section 830 of this title;"],[1,"(11) to distribute a laboratory supply to a person who uses, or attempts to use, that laboratory supply to manufacture a controlled substance or a listed chemical, in violation of this subchapter or subchapter II, with reckless disregard for the illegal uses to which such a laboratory supply will be put;"],[1,"(12) who is a regulated seller, or a distributor required to submit reports under subsection (b)(3) of section 830 of this title—"],[2,"(A) to sell at retail a scheduled listed chemical product in violation of paragraph (1) of subsection (d) of such section, knowing at the time of the transaction involved (independent of consulting the logbook under subsection (e)(1)(A)(iii) of such section) that the transaction is a violation; or"],[2,"(B) to knowingly or recklessly sell at retail such a product in violation of paragraph (2) of such subsection (d);"],[1,"(13) who is a regulated seller to knowingly or recklessly sell at retail a scheduled listed chemical product in violation of subsection (e) of such section;"],[1,"(14) who is a regulated seller or an employee or agent of such seller to disclose, in violation of regulations under subparagraph (C) of section 830(e)(1) of this title, information in logbooks under subparagraph (A)(iii) of such section, or to refuse to provide such a logbook to Federal, State, or local law enforcement authorities;"],[1,"(15) to distribute a scheduled listed chemical product to a regulated seller, or to a regulated person referred to in section 830(b)(3)(B) of this title, unless such regulated seller or regulated person is, at the time of such distribution, currently registered with the Drug Enforcement Administration, or on the list of persons referred to under section 830(e)(1)(B)(v) of this title;"],[1,"(16) to violate subsection (e) of section 825 of this title; 2 or"],[1,"(17) in the case of a registered manufacturer or distributor of opioids, to fail to review the most recent information, directly related to the customers of the manufacturer or distributor, made available by the Attorney General in accordance with section 827(f) of this title."],[0,"As used in paragraph (11), the term \"laboratory supply\" means a listed chemical or any chemical, substance, or item on a special surveillance list published by the Attorney General, which contains chemicals, products, materials, or equipment used in the manufacture of controlled substances and listed chemicals. For purposes of paragraph (11), there is a rebuttable presumption of reckless disregard at trial if the Attorney General notifies a firm in writing that a laboratory supply sold by the firm, or any other person or firm, has been used by a customer of the notified firm, or distributed further by that customer, for the unlawful production of controlled substances or listed chemicals a firm distributes and 2 weeks or more after the notification the notified firm distributes a laboratory supply to the customer. For purposes of paragraph (15), if the distributor is temporarily unable to access the list of persons referred to under section 830(e)(1)(B)(v) of this title, the distributor may rely on a written, faxed, or electronic copy of a certificate of self-certification submitted by the regulated seller or regulated person, provided the distributor confirms within 7 business days of the distribution that such regulated seller or regulated person is on the list referred to under section 830(e)(1)(B)(v) of this title."],[0,"(b) Manufacture"],[0,"It shall be unlawful for any person who is a registrant to manufacture a controlled substance in schedule I or II, or ephedrine, pseudoephedrine, or phenylpropanolamine or any of the salts, optical isomers, or salts of optical isomers of such chemical, which is—"],[1,"(1) not expressly authorized by his registration and by a quota assigned to him pursuant to section 826 of this title; or"],[1,"(2) in excess of a quota assigned to him pursuant to section 826 of this title."],[0,"(c) Penalties"],[0,"(1)(A) Except as provided in subparagraph (B), (C), or (D) of this paragraph and paragraph (2), any person who violates this section shall, with respect to any such violation, be subject to a civil penalty of not more than $25,000. The district courts of the United States (or, where there is no such court in the case of any territory or possession of the United States, then the court in such territory or possession having the jurisdiction of a district court of the United States in cases arising under the Constitution and laws of the United States) shall have jurisdiction in accordance with section 1355 of title 28 to enforce this paragraph."],[0,"(B)(i) Except as provided in clause (ii), in the case of a violation of paragraph (5), (10), or (17) of subsection (a), the civil penalty shall not exceed $10,000."],[0,"(ii) In the case of a violation described in clause (i) committed by a registered manufacturer or distributor of opioids and related to the reporting of suspicious orders for opioids, failing to maintain effective controls against diversion of opioids, or failing to review the most recent information made available by the Attorney General in accordance with section 827(f) of this title, the penalty shall not exceed $100,000."],[0,"(C) In the case of a violation of paragraph (16) of subsection (a) of this section by an importer, exporter, manufacturer, or distributor (other than as provided in subparagraph (D)), up to $500,000 per violation. For purposes of this subparagraph, a violation is defined as each instance of importation, exportation, manufacturing, distribution, or possession with intent to manufacture or distribute, in violation of paragraph (16) of subsection (a)."],[0,"(D) In the case of a distribution, dispensing, or possession with intent to distribute or dispense in violation of paragraph (16) of subsection (a) of this section at the retail level, up to $1000 per violation. For purposes of this paragraph, the term \"at the retail level\" refers to products sold, or held for sale, directly to the consumer for personal use. Each package, container or other separate unit containing an anabolic steroid that is distributed, dispensed, or possessed with intent to distribute or dispense at the retail level in violation of such paragraph (16) of subsection (a) shall be considered a separate violation."],[0,"(2)(A) If a violation of this section is prosecuted by an information or indictment which alleges that the violation was committed knowingly and the trier of fact specifically finds that the violation was so committed, such person shall, except as otherwise provided in subparagraph (B) or (D) of this paragraph, be sentenced to imprisonment of not more than one year or a fine under title 18, or both."],[0,"(B) If a violation referred to in subparagraph (A) was committed after one or more prior convictions of the offender for an offense punishable under this paragraph (2), or for a crime under any other provision of this subchapter or subchapter II or other law of the United States relating to narcotic drugs, marihuana, or depressant or stimulant substances, have become final, such person shall be sentenced to a term of imprisonment of not more than 2 years, a fine under title 18, or both."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/21/842?type=usc&year=mostrecent&link-type=html"},"head":"§842. Prohibited acts B","tname":"Food and Drugs","by":{"0":"23, 23, 24, 23","1":"16, 26, 26, 26, 26, 27","4":"17, 17, 17"}},{"t":"usc","label":"21 U.S.C. § 885","url":"https://www.law.cornell.edu/uscode/text/21/885","subs":["(a)(1)"],"stext":{"head":"§885. Burden of proof; liabilities","paras":[[0,"(a) Exemptions and exceptions; presumption in simple possession offenses"],[0,"(1) It shall not be necessary for the United States to negative any exemption or exception set forth in this subchapter in any complaint, information, indictment, or other pleading or in any trial, hearing, or other proceeding under this subchapter, and the burden of going forward with the evidence with respect to any such exemption or exception shall be upon the person claiming its benefit."],[0,"(2) In the case of a person charged under section 844(a) of this title with the possession of a controlled substance, any label identifying such substance for purposes of section 353(b)(2) of this title shall be admissible in evidence and shall be prima facie evidence that such substance was obtained pursuant to a valid prescription from a practitioner while acting in the course of his professional practice."],[0,"(b) Registration and order forms"],[0,"In the absence of proof that a person is the duly authorized holder of an appropriate registration or order form issued under this subchapter, he shall be presumed not to be the holder of such registration or form, and the burden of going forward with the evidence with respect to such registration or form shall be upon him."],[0,"(c) Use of vehicles, vessels, and aircraft"],[0,"The burden of going forward with the evidence to establish that a vehicle, vessel, or aircraft used in connection with controlled substances in schedule I was used in accordance with the provisions of this subchapter shall be on the persons engaged in such use."],[0,"(d) Immunity of Federal, State, local and other officials"],[0,"Except as provided in sections 2234 and 2235 of title 18, no civil or criminal liability shall be imposed by virtue of this subchapter upon any duly authorized Federal officer lawfully engaged in the enforcement of this subchapter, or upon any duly authorized officer of any State, territory, political subdivision thereof, the District of Columbia, or any possession of the United States, who shall be lawfully engaged in the enforcement of any law or municipal ordinance relating to controlled substances."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/21/885?type=usc&year=mostrecent&link-type=html"},"op":13,"ar":1,"head":"§885. Burden of proof; liabilities","tname":"Food and Drugs","by":{"0":"21","2":"29, 31"}},{"t":"usc","label":"42 U.S.C. § 290bb-2a","url":"https://www.law.cornell.edu/uscode/text/42/290bb-2a","by":{"0":"39"}},{"t":"law","label":"Pub. L. No. 91-513","url":"https://www.govinfo.gov/link/statute/84/1236","by":{"0":"28","2":"3, 29, 31"}},{"t":"reg","label":"21 C.F.R. § 1306.04","url":"https://www.ecfr.gov/current/title-21/section-1306.04","subs":["(a)"],"by":{"0":"passim","1":"17, 18, 2, 3","2":"20","3":"1, 5, 11, 19"}},{"t":"case","label":"Borden v. United States","cite":"141 S. Ct. 1817","y":2021,"id":"2020/19-5410","sc":1,"sum":"The decision of the Sixth Circuit—holding that an offense with a mental state of recklessness may qualify as a “violent felony” under the Armed Career Criminal Act’s elements clause, 18 U. S. C. §924(e)(2)(B)(i)—is reversed, and the case is remanded.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"30, 32"}},{"t":"case","label":"Colautti v. Franklin","cite":"439 U.S. 379","y":1979,"id":"1978/77-891","sc":1,"sum":"Section 5 (a) of the Pennsylvania Abortion Control Act requires every person who performs an abortion to make a determination, \"based on his experience, judgment or professional competence,\" that the fetus is not viable. If such person determines that the fetus \"is viable,\" or \"if there is sufficient reason to believe that the fetus may be viable,\" then he must exercise the same care to preserve the fetus' life and …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"42, 48","3":"10"}},{"t":"case","label":"DuVall v. United States","cite":"82 F.2d 382","y":1936,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/82/382/","by":{"1":"37, 39"}},{"t":"case","label":"Grayned v. City of Rockford","cite":"408 U.S. 104","y":1972,"id":"1971/70-5106","sc":1,"sum":"1. Antipicketing ordinance, virtually identical with one invalidated as violative of equal protection in Police Department of Chicago v. Mosley, ante, p. 92, is likewise invalid.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"50"}},{"t":"case","label":"Heller v. United States","cite":"104 F.2d 446","y":1939,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.2d/104/446/","by":{"1":"38"}},{"t":"case","label":"Humphreys v. Drug Enf ’t Admin.","cite":"96 F.3d 658","y":1996,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/96/658/","by":{"1":"45"}},{"t":"case","label":"Johnson v. United States","cite":"135 S. Ct. 2551","y":2015,"id":"2014/13-7120","sc":1,"sum":"The Court determined that the residual clause of the Armed Criminal Career Act is unconstitutionally vague.","sumSrc":"Oyez","by":{"1":"13, 34, 42, 48, 50","3":"6"}},{"t":"case","label":"Kolender v. Lawson","cite":"461 U.S. 352","y":1983,"id":"1982/81-1320","sc":1,"sum":"The law was unconstitutionally vague because it gave excessive discretion to the police (in the absence of probable cause for an arrest) whether to stop and interrogate a suspect or leave him alone. The majority hinted that the California statute compromised the constitutional right to freedom of movement.","sumSrc":"Oyez","by":{"1":"43"}},{"t":"case","label":"McBride v. United States","cite":"225 F.2d 249","y":1955,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/225/249/","by":{"1":"46"}},{"t":"case","label":"McFadden v. United States","cite":"576 U.S. 186","y":2015,"id":"2014/14-378","sc":1,"sum":"The Court decided that in order to fulfill the intent element of The Controlled Substance Analogue Enforcement Act of 1986, a person must either know that the substance is a controlled substance or be aware of what the substance is without knowing that it is controlled.","sumSrc":"Oyez","by":{"1":"12, 24, 31"}},{"t":"case","label":"Papachristou v. Jacksonville","cite":"405 U.S. 156","y":1972,"id":"1971/70-5030","sc":1,"sum":"The Jacksonville vagrancy ordinance, under which petitioners were convicted, is void for vagueness, in that it \"fails to give a person of ordinary intelligence fair notice that his contemplated conduct is forbidden by the statute,\" it encourages arbitrary and erratic arrests and convictions, it makes criminal activities that by modern standards are normally innocent, and it places almost unfettered discretion in the …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"48"}},{"t":"case","label":"Posters ‘N’ Things, Ltd. v. United States","cite":"511 U.S. 513","y":1994,"id":"1993/92-903","sc":1,"op":2,"sum":"Noting that “a severe penalty is a further factor tending to suggest that . . . the usual presumption that a defendant must know the facts that make his conduct illegal should apply”.","sumSrc":"opinion","by":{"1":"14, 32"}},{"t":"case","label":"Sessions v. Dimaya","cite":"138 S. Ct. 1204","y":2018,"id":"2017/15-1498","sc":1,"sum":"A case in which the Court struck down the Immigration and Nationality Act’s “crime of violence” provision as unconstitutionally vague in violation of the Due Process Clause of the Fifth Amendment.","sumSrc":"Oyez","by":{"1":"43"}},{"t":"case","label":"Strader v. United States","cite":"72 F.2d 589","y":1934,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.2d/72/589/","by":{"1":"39"}},{"t":"case","label":"Teter v. United States","cite":"12 F.2d 224","y":1926,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/12/224/","by":{"1":"38"}},{"t":"case","label":"Towbin v. United States","cite":"93 F.2d 861","y":1938,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.2d/93/861/","by":{"1":"37"}},{"t":"case","label":"United States v. Abovyan","cite":"988 F.3d 1288","y":2021,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/988/1288/","by":{"1":"44"}},{"t":"case","label":"United States v. Anthony","cite":"15 F. Supp. 553","y":1936,"court":"S.D. Cal.","url":"https://www.courtlistener.com/c/F.%20Supp./15/553/","by":{"1":"36, 37"}},{"t":"case","label":"United States v. Armstrong","cite":"550 F.3d 382","y":2008,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/550/382/","by":{"1":"15, 34, 40","3":"11"}},{"t":"case","label":"United States v. August","cite":"984 F.2d 705","y":1992,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/984/705/","by":{"1":"44"}},{"t":"case","label":"United States v. Bartee","cite":"479 F.2d 484","y":1973,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.2d/479/484/","by":{"1":"41"}},{"t":"case","label":"United States v. Bek","cite":"493 F.3d 790","y":2007,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/493/790/","by":{"1":"15, 34"}},{"t":"case","label":"United States v. Boettjer","cite":"569 F.2d 1078","y":1978,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/569/1078/","by":{"1":"35, 41, 46","3":"5"}},{"t":"case","label":"United States v. Bush","cite":"6 F.2d 303","y":1925,"court":"W.D. La.","url":"https://www.courtlistener.com/c/F.2d/6/303/","by":{"1":"38"}},{"t":"case","label":"United States v. Collier","cite":"478 F.2d 268","y":1973,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/478/268/","by":{"1":"42"}},{"t":"case","label":"United States v. Godofsky","cite":"943 F.3d 1011","y":2019,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/943/1011/","by":{"1":"15"}},{"t":"case","label":"United States v. Goldstein","cite":"695 F.2d 1228","y":1981,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.2d/695/1228/","by":{"1":"44"}},{"t":"case","label":"United States v. Int’l Mins. & Chem. Corp.","cite":"402 U.S. 558","y":1971,"id":"1970/557","sc":1,"sum":"Appellee was charged by information with shipping sulfuric and hydrofluosilicic acids in interstate commerce and that it \"did knowingly fail to show on the shipping papers the required classification of said property, to wit, Corrosive Liquid, in violation of 49 C. F. R. 173.437,\" issued pursuant to 18 U. S. C. § 834 (a). Section 834 (f) provides that whoever \"knowingly violates any such regulation\" shall be fined …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"21"}},{"t":"case","label":"United States v. Jackson","cite":"576 F.2d 46","y":1978,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/576/46/","by":{"1":"40"}},{"t":"case","label":"United States v. Jin Fuey Moy","cite":"241 U.S. 394","y":1916,"id":"scdb/1915-167","sc":1,"sum":"A statute must be so construed, if fairly possible, as to avoid not only the conclusion that it is unconstitutional, but also grave doubts upon that score. United States v. Delaware & Hudson Co., 213 TJ. S. 366.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"23"}},{"t":"case","label":"United States v. Jobe","cite":"487 F.2d 268","y":1973,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.2d/487/268/","by":{"1":"41"}},{"t":"case","label":"United States v. Kahn","cite":"989 F.3d 806","y":2021,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/989/806/","op":10,"ar":2,"by":{"1":"1, 11, 29, 32, 33"}},{"t":"case","label":"United States v. Kirk","cite":"584 F.2d 773","y":1978,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/584/773/","by":{"1":"40, 44","3":"11"}},{"t":"case","label":"United States v. Leal","cite":"75 F.3d 219","y":1996,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/75/219/","by":{"1":"45"}},{"t":"case","label":"United States v. Lee","cite":"966 F.3d 310","y":2020,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/966/310/","by":{"1":"51"}},{"t":"case","label":"United States v. Li","cite":"819 F. App’x 111","y":2020,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/819/111/","by":{"1":"15"}},{"t":"case","label":"United States v. Limberopoulos","cite":"26 F.3d 245","y":1994,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/26/245/","by":{"1":"15, 34"}},{"t":"case","label":"United States v. Merrill","cite":"513 F.3d 1293","y":2008,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/513/1293/","by":{"1":"12, 45","3":"5"}},{"t":"case","label":"United States v. Naum","cite":"832 F. App’x 137","y":2020,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/832/137/","by":{"1":"33, 36, 45, 46"}},{"t":"case","label":"United States v. Nelson","cite":"383 F.3d 1227","y":2004,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/383/1227/","by":{"1":"15, 34, 40","2":"38"}},{"t":"case","label":"United States v. Norris","cite":"780 F.2d 1207","y":1986,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/780/1207/","by":{"1":"33, 45"}},{"t":"case","label":"United States v. Plesons","cite":"560 F.2d 890","y":1977,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/560/890/","by":{"1":"40"}},{"t":"case","label":"United States v. Ruan","cite":"966 F.3d 1101","y":2020,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/966/1101/","op":1,"by":{"1":"33, 47"}},{"t":"case","label":"United States v. Singh","cite":"54 F.3d 1182","y":1995,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/54/1182/","by":{"1":"44"}},{"t":"case","label":"United States v. Stump","cite":"735 F.2d 273","y":1984,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/735/273/","by":{"1":"45, 46"}},{"t":"case","label":"United States v. Temeck","cite":"2018 WL 3609503","y":2018,"court":"S.D. Ohio July 27","by":{"1":"44"}},{"t":"case","label":"White v. United States","cite":"399 F.2d 813","y":1968,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/399/813/","by":{"1":"39"}},{"t":"case","label":"Workin v. United States","cite":"260 F. 137","y":1919,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F./260/137/","by":{"1":"38"}},{"t":"const","label":"Amendment V","clauses":[["grand-jury","Grand Jury Clause"],["double-jeopardy","Double Jeopardy Clause"],["self-incrimination","Self-Incrimination Clause"],["due-process-5","Due Process Clause (Fifth Amendment)"],["takings","Takings Clause"]],"text":"No person shall be held to answer for a capital, or otherwise infamous crime, unless on a presentment or indictment of a Grand Jury, except in cases arising in the land or naval forces, or in the Militia, when in actual service in time of War or public danger; nor shall any person be subject for the same offence to be twice put in jeopardy of life or limb; nor shall be compelled in any criminal case to be a witness against himself, nor be deprived of life, liberty, or property, without due process of law; nor shall private property be taken for public use, without just compensation.","by":{"1":"1"}},{"t":"usc","label":"18 U.S.C. § 841","url":"https://www.law.cornell.edu/uscode/text/18/841","subs":["(a)(1)"],"stext":{"head":"§841. Definitions","paras":[[0,"As used in this chapter—"],[1,"(a) \"Person\" means any individual, corporation, company, association, firm, partnership, society, or joint stock company."],[1,"(b) \"Interstate\" or foreign commerce means commerce between any place in a State and any place outside of that State, or within any possession of the United States (not including the Canal Zone) or the District of Columbia, and commerce between places within the same State but through any place outside of that State. \"State\" includes the District of Columbia, the Commonwealth of Puerto Rico, and the possessions of the United States (not including the Canal Zone)."],[1,"(c) \"Explosive materials\" means explosives, blasting agents, and detonators."],[1,"(d) Except for the purposes of subsections (d), (e), (f), (g), (h), (i), and (j) of section 844 of this title, \"explosives\" means any chemical compound mixture, or device, the primary or common purpose of which is to function by explosion; the term includes, but is not limited to, dynamite and other high explosives, black powder, pellet powder, initiating explosives, detonators, safety fuses, squibs, detonating cord, igniter cord, and igniters. The Attorney General shall publish and revise at least annually in the Federal Register a list of these and any additional explosives which he determines to be within the coverage of this chapter. For the purposes of subsections (d), (e), (f), (g), (h), and (i) of section 844 of this title, the term \"explosive\" is defined in subsection (j) of such section 844."],[1,"(e) \"Blasting agent\" means any material or mixture, consisting of fuel and oxidizer, intended for blasting, not otherwise defined as an explosive: Provided, That the finished product, as mixed for use or shipment, cannot be detonated by means of a numbered 8 test blasting cap when unconfined."],[1,"(f) \"Detonator\" means any device containing a detonating charge that is used for initiating detonation in an explosive; the term includes, but is not limited to, electric blasting caps of instantaneous and delay types, blasting caps for use with safety fuses and detonating-cord delay connectors."],[1,"(g) \"Importer\" means any person engaged in the business of importing or bringing explosive materials into the United States for purposes of sale or distribution."],[1,"(h) \"Manufacturer\" means any person engaged in the business of manufacturing explosive materials for purposes of sale or distribution or for his own use."],[1,"(i) \"Dealer\" means any person engaged in the business of distributing explosive materials at wholesale or retail."],[1,"(j) \"Permittee\" means any user of explosives for a lawful purpose, who has obtained either a user permit or a limited permit under the provisions of this chapter."],[1,"(k) \"Attorney General\" means the Attorney General of the United States."],[1,"(l) \"Crime punishable by imprisonment for a term exceeding one year\" shall not mean (1) any Federal or State offenses pertaining to antitrust violations, unfair trade practices, restraints of trade, or other similar offenses relating to the regulation of business practices as the Attorney General may by regulation designate, or (2) any State offense (other than one involving a firearm or explosive) classified by the laws of the State as a misdemeanor and punishable by a term of imprisonment of two years or less."],[1,"(m) \"Licensee\" means any importer, manufacturer, or dealer licensed under the provisions of this chapter."],[1,"(n) \"Distribute\" means sell, issue, give, transfer, or otherwise dispose of."],[1,"(o) \"Convention on the Marking of Plastic Explosives\" means the Convention on the Marking of Plastic Explosives for the Purpose of Detection, Done at Montreal on 1 March 1991."],[1,"(p) \"Detection agent\" means any one of the substances specified in this subsection when introduced into a plastic explosive or formulated in such explosive as a part of the manufacturing process in such a manner as to achieve homogeneous distribution in the finished explosive, including—"],[2,"(1) Ethylene glycol dinitrate (EGDN), C2H4(NO3)2, molecular weight 152, when the minimum concentration in the finished explosive is 0.2 percent by mass;"],[2,"(2) 2,3-Dimethyl-2,3-dinitrobutane (DMNB), C6H12(NO2)2, molecular weight 176, when the minimum concentration in the finished explosive is 0.1 percent by mass;"],[2,"(3) Para-Mononitrotoluene (p-MNT), C7H7NO2, molecular weight 137, when the minimum concentration in the finished explosive is 0.5 percent by mass;"],[2,"(4) Ortho-Mononitrotoluene (o-MNT), C7H7NO2, molecular weight 137, when the minimum concentration in the finished explosive is 0.5 percent by mass; and"],[2,"(5) any other substance in the concentration specified by the Attorney General, after consultation with the Secretary of State and the Secretary of Defense, that has been added to the table in part 2 of the Technical Annex to the Convention on the Marking of Plastic Explosives."],[1,"(q) \"Plastic explosive\" means an explosive material in flexible or elastic sheet form formulated with one or more high explosives which in their pure form has a vapor pressure less than 10−4 Pa at a temperature of 25°C., is formulated with a binder material, and is as a mixture malleable or flexible at normal room temperature."],[1,"(r) \"Alien\" means any person who is not a citizen or national of the United States."],[1,"(s) \"Responsible person\" means an individual who has the power to direct the management and policies of the applicant pertaining to explosive materials."],[1,"(t) Indian Tribe 1.—The term \"Indian tribe\" has the meaning given the term in section 102 of the Federally Recognized Indian Tribe List Act of 1994 (25 U.S.C. 479a)).2, 3"]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/841?type=usc&year=mostrecent&link-type=html"},"head":"§841. Definitions","tname":"Crimes and Criminal Procedure","by":{"1":"2","3":"1, 5, 10"}},{"t":"usc","label":"21 U.S.C. § 802","url":"https://www.law.cornell.edu/uscode/text/21/802","subs":["(21)","(20)(1970)","(56)(C)"],"stext":{"head":"§802. Definitions","paras":[[0,"As used in this subchapter:"],[0,"(1) The term \"addict\" means any individual who habitually uses any narcotic drug so as to endanger the public morals, health, safety, or welfare, or who is so far addicted to the use of narcotic drugs as to have lost the power of self-control with reference to his addiction."],[0,"(2) The term \"administer\" refers to the direct application of a controlled substance to the body of a patient or research subject by—"],[1,"(A) a practitioner (or, in his presence, by his authorized agent), or"],[1,"(B) the patient or research subject at the direction and in the presence of the practitioner,"],[0,"whether such application be by injection, inhalation, ingestion, or any other means."],[0,"(3) The term \"agent\" means an authorized person who acts on behalf of or at the direction of a manufacturer, distributor, or dispenser; except that such term does not include a common or contract carrier, public warehouseman, or employee of the carrier or warehouseman, when acting in the usual and lawful course of the carrier's or warehouseman's business."],[0,"(4) The term \"Drug Enforcement Administration\" means the Drug Enforcement Administration in the Department of Justice."],[0,"(5) The term \"control\" means to add a drug or other substance, or immediate precursor, to a schedule under part B of this subchapter, whether by transfer from another schedule or otherwise."],[0,"(6) The term \"controlled substance\" means a drug or other substance, or immediate precursor, included in schedule I, II, III, IV, or V of part B of this subchapter. The term does not include distilled spirits, wine, malt beverages, or tobacco, as those terms are defined or used in subtitle E of the Internal Revenue Code of 1986."],[0,"(7) The term \"counterfeit substance\" means a controlled substance which, or the container or labeling of which, without authorization, bears the trademark, trade name, or other identifying mark, imprint, number, or device, or any likeness thereof, of a manufacturer, distributor, or dispenser other than the person or persons who in fact manufactured, distributed, or dispensed such substance and which thereby falsely purports or is represented to be the product of, or to have been distributed by, such other manufacturer, distributor, or dispenser."],[0,"(8) The terms \"deliver\" or \"delivery\" mean the actual, constructive, or attempted transfer of a controlled substance or a listed chemical, whether or not there exists an agency relationship."],[0,"(9) The term \"depressant or stimulant substance\" means—"],[1,"(A) a drug which contains any quantity of barbituric acid or any of the salts of barbituric acid; or"],[1,"(B) a drug which contains any quantity of (i) amphetamine or any of its optical isomers; (ii) any salt of amphetamine or any salt of an optical isomer of amphetamine; or (iii) any substance which the Attorney General, after investigation, has found to be, and by regulation designated as, habit forming because of its stimulant effect on the central nervous system; or"],[1,"(C) lysergic acid diethylamide; or"],[1,"(D) any drug which contains any quantity of a substance which the Attorney General, after investigation, has found to have, and by regulation designated as having, a potential for abuse because of its depressant or stimulant effect on the central nervous system or its hallucinogenic effect."],[0,"(10) The term \"dispense\" means to deliver a controlled substance to an ultimate user or research subject by, or pursuant to the lawful order of, a practitioner, including the prescribing and administering of a controlled substance and the packaging, labeling or compounding necessary to prepare the substance for such delivery. The term \"dispenser\" means a practitioner who so delivers a controlled substance to an ultimate user or research subject."],[0,"(11) The term \"distribute\" means to deliver (other than by administering or dispensing) a controlled substance or a listed chemical. The term \"distributor\" means a person who so delivers a controlled substance or a listed chemical."],[0,"(12) The term \"drug\" has the meaning given that term by section 321(g)(1) of this title."],[0,"(13) The term \"felony\" means any Federal or State offense classified by applicable Federal or State law as a felony."],[0,"(14) The term \"isomer\" means the optical isomer, except as used in schedule I(c) and schedule II(a)(4). As used in schedule I(c), the term \"isomer\" means any optical, positional, or geometric isomer. As used in schedule II(a)(4), the term \"isomer\" means any optical or geometric isomer."],[0,"(15) The term \"manufacture\" means the production, preparation, propagation, compounding, or processing of a drug or other substance, either directly or indirectly or by extraction from substances of natural origin, or independently by means of chemical synthesis or by a combination of extraction and chemical synthesis, and includes any packaging or repackaging of such substance or labeling or relabeling of its container; except that such term does not include the preparation, compounding, packaging, or labeling of a drug or other substance in conformity with applicable State or local law by a practitioner as an incident to his administration or dispensing of such drug or substance in the course of his professional practice. The term \"manufacturer\" means a person who manufactures a drug or other substance."],[0,"(16)(A) Subject to subparagraph (B), the terms \"marihuana\" and \"marijuana\" mean all parts of the plant Cannabis sativa L., whether growing or not; the seeds thereof; the resin extracted from any part of such plant; and every compound, manufacture, salt, derivative, mixture, or preparation of such plant, its seeds or resin."],[0,"(B) The terms \"marihuana\" and \"marijuana\" do not include—"],[1,"(i) hemp, as defined in section 1639o of title 7; or"],[1,"(ii) the mature stalks of such plant, fiber produced from such stalks, oil or cake made from the seeds of such plant, any other compound, manufacture, salt, derivative, mixture, or preparation of such mature stalks (except the resin extracted therefrom), fiber, oil, or cake, or the sterilized seed of such plant which is incapable of germination."],[0,"(17) The term \"narcotic drug\" means any of the following whether produced directly or indirectly by extraction from substances of vegetable origin, or independently by means of chemical synthesis, or by a combination of extraction and chemical synthesis:"],[1,"(A) Opium, opiates, derivatives of opium and opiates, including their isomers, esters, ethers, salts, and salts of isomers, esters, and ethers, whenever the existence of such isomers, esters, ethers, and salts is possible within the specific chemical designation. Such term does not include the isoquinoline alkaloids of opium."],[1,"(B) Poppy straw and concentrate of poppy straw."],[1,"(C) Coca leaves, except coca leaves and extracts of coca leaves from which cocaine, ecgonine, and derivatives of ecgonine or their salts have been removed."],[1,"(D) Cocaine, its salts, optical and geometric isomers, and salts of isomers."],[1,"(E) Ecgonine, its derivatives, their salts, isomers, and salts of isomers."],[1,"(F) Any compound, mixture, or preparation which contains any quantity of any of the substances referred to in subparagraphs (A) through (E)."],[0,"(18) The term \"opiate\" or \"opioid\" means any drug or other substance having an addiction-forming or addiction-sustaining liability similar to morphine or being capable of conversion into a drug having such addiction-forming or addiction-sustaining liability."],[0,"(19) The term \"opium poppy\" means the plant of the species Papaver somniferum L., except the seed thereof."],[0,"(20) The term \"poppy straw\" means all parts, except the seeds, of the opium poppy, after mowing."],[0,"(21) The term \"practitioner\" means a physician, dentist, veterinarian, scientific investigator, pharmacy, hospital, or other person licensed, registered, or otherwise permitted, by the United States or the jurisdiction in which he practices or does research, to distribute, dispense, conduct research with respect to, administer, or use in teaching or chemical analysis, a controlled substance in the course of professional practice or research."],[0,"(22) The term \"production\" includes the manufacture, planting, cultivation, growing, or harvesting of a controlled substance."],[0,"(23) The term \"immediate precursor\" means a substance—"],[1,"(A) which the Attorney General has found to be and by regulation designated as being the principal compound used, or produced primarily for use, in the manufacture of a controlled substance;"],[1,"(B) which is an immediate chemical intermediary used or likely to be used in the manufacture of such controlled substance; and"],[1,"(C) the control of which is necessary to prevent, curtail, or limit the manufacture of such controlled substance."],[0,"(24) The term \"Secretary\", unless the context otherwise indicates, means the Secretary of Health and Human Services."],[0,"(25) The term \"serious bodily injury\" means bodily injury which involves—"],[1,"(A) a substantial risk of death;"],[1,"(B) protracted and obvious disfigurement; or"],[1,"(C) protracted loss or impairment of the function of a bodily member, organ, or mental faculty."],[0,"(26) The term \"State\" means a State of the United States, the District of Columbia, and any commonwealth, territory, or possession of the United States."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/21/802?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§802. Definitions","tname":"Food and Drugs","by":{"1":"17","2":"30, 21, 21"}},{"t":"usc","label":"21 U.S.C. § 821","url":"https://www.law.cornell.edu/uscode/text/21/821","stext":{"head":"§821. Rules and regulations","paras":[[0,"The Attorney General is authorized to promulgate rules and regulations and to charge reasonable fees relating to the registration and control of the manufacture, distribution, and dispensing of controlled substances and to listed chemicals."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/21/821?type=usc&year=mostrecent&link-type=html"},"head":"§821. Rules and regulations","tname":"Food and Drugs","by":{"1":"16","2":"43"}},{"t":"usc","label":"21 U.S.C. § 843","url":"https://www.law.cornell.edu/uscode/text/21/843","subs":["(b)"],"stext":{"head":"§843. Prohibited acts C","paras":[[0,"(a) Unlawful acts"],[0,"It shall be unlawful for any person knowingly or intentionally—"],[1,"(1) who is a registrant to distribute a controlled substance classified in schedule I or II, in the course of his legitimate business, except pursuant to an order or an order form as required by section 828 of this title;"],[1,"(2) to use in the course of the manufacture, distribution, or dispensing of a controlled substance, or to use for the purpose of acquiring or obtaining a controlled substance, a registration number which is fictitious, revoked, suspended, expired, or issued to another person;"],[1,"(3) to acquire or obtain possession of a controlled substance by misrepresentation, fraud, forgery, deception, or subterfuge;"],[1,"(4)(A) to furnish false or fraudulent material information in, or omit any material information from, any application, report, record, or other document required to be made, kept, or filed under this subchapter or subchapter II, or (B) to present false or fraudulent identification where the person is receiving or purchasing a listed chemical and the person is required to present identification under section 830(a) of this title;"],[1,"(5) to make, distribute, or possess any punch, die, plate, stone, or other thing designed to print, imprint, or reproduce the trademark, trade name, or other identifying mark, imprint, or device of another or any likeness of any of the foregoing upon any drug or container or labeling thereof so as to render such drug a counterfeit substance;"],[1,"(6) to possess any three-neck round-bottom flask, tableting machine, encapsulating machine, or gelatin capsule, or any equipment, chemical, product, or material which may be used to manufacture a controlled substance or listed chemical, knowing, intending, or having reasonable cause to believe, that it will be used to manufacture a controlled substance or listed chemical in violation of this subchapter or subchapter II;"],[1,"(7) to manufacture, distribute, export, or import any three-neck round-bottom flask, tableting machine, encapsulating machine, or gelatin capsule, or any equipment, chemical, product, or material which may be used to manufacture a controlled substance or listed chemical, knowing, intending, or having reasonable cause to believe, that it will be used to manufacture a controlled substance or listed chemical in violation of this subchapter or subchapter II or, in the case of an exportation, in violation of this subchapter or subchapter II or of the laws of the country to which it is exported;"],[1,"(8) to create a chemical mixture for the purpose of evading a requirement of section 830 of this title or to receive a chemical mixture created for that purpose; or"],[1,"(9) to distribute, import, or export a list I chemical without the registration required by this subchapter or subchapter II."],[0,"(b) Communication facility"],[0,"It shall be unlawful for any person knowingly or intentionally to use any communication facility in committing or in causing or facilitating the commission of any act or acts constituting a felony under any provision of this subchapter or subchapter II. Each separate use of a communication facility shall be a separate offense under this subsection. For purposes of this subsection, the term \"communication facility\" means any and all public and private instrumentalities used or useful in the transmission of writing, signs, signals, pictures, or sounds of all kinds and includes mail, telephone, wire, radio, and all other means of communication."],[0,"(c) Advertisement"],[0,"(1) It shall be unlawful for any person to place in any newspaper, magazine, handbill, or other publications, any written advertisement knowing that it has the purpose of seeking or offering illegally to receive, buy, or distribute a Schedule 1 I controlled substance. As used in this section the term \"advertisement\" includes, in addition to its ordinary meaning, such advertisements as those for a catalog of Schedule 1 I controlled substances and any similar written advertisement that has the purpose of seeking or offering illegally to receive, buy, or distribute a Schedule 1 I controlled substance. The term \"advertisement\" does not include material which merely advocates the use of a similar material, which advocates a position or practice, and does not attempt to propose or facilitate an actual transaction in a Schedule 1 I controlled substance."],[0,"(2)(A) It shall be unlawful for any person to knowingly or intentionally use the Internet, or cause the Internet to be used, to advertise the sale of, or to offer to sell, distribute, or dispense, a controlled substance where such sale, distribution, or dispensing is not authorized by this subchapter or by the Controlled Substances Import and Export Act [21 U.S.C. 951 et seq.]."],[0,"(B) Examples of activities that violate subparagraph (A) include, but are not limited to, knowingly or intentionally causing the placement on the Internet of an advertisement that refers to or directs prospective buyers to Internet sellers of controlled substances who are not registered with a modification under section 823(g) of this title."],[0,"(C) Subparagraph (A) does not apply to material that either—"],[1,"(i) merely advertises the distribution of controlled substances by nonpractitioners to the extent authorized by their registration under this subchapter; or"],[1,"(ii) merely advocates the use of a controlled substance or includes pricing information without attempting to facilitate an actual transaction involving a controlled substance."],[0,"(d) Penalties"],[0,"(1) Except as provided in paragraph (2), any person who violates this section shall be sentenced to a term of imprisonment of not more than 4 years, a fine under title 18, or both; except that if any person commits such a violation after one or more prior convictions of him for violation of this section, or for a felony under any other provision of this subchapter or subchapter II or other law of the United States relating to narcotic drugs, marihuana, or depressant or stimulant substances, have become final, such person shall be sentenced to a term of imprisonment of not more than 8 years, a fine under title 18, or both."],[0,"(2) Any person who, with the intent to manufacture or to facilitate the manufacture of methamphetamine, violates paragraph (6) or (7) of subsection (a), shall be sentenced to a term of imprisonment of not more than 10 years, a fine under title 18, or both; except that if any person commits such a violation after one or more prior convictions of that person—"],[1,"(A) for a violation of paragraph (6) or (7) of subsection (a);"],[1,"(B) for a felony under any other provision of this subchapter or subchapter II of this chapter; 2 or"],[1,"(C) under any other law of the United States or any State relating to controlled substances or listed chemicals,"],[0,"has become final, such person shall be sentenced to a term of imprisonment of not more than 20 years, a fine under title 18, or both."],[0,"(e) Additional penalties"],[0,"In addition to any other applicable penalty, any person convicted of a felony violation of this section relating to the receipt, distribution, manufacture, exportation, or importation of a listed chemical may be enjoined from engaging in any transaction involving a listed chemical for not more than ten years."],[0,"(f) Injunctions"],[0,"(1) In addition to any penalty provided in this section, the Attorney General is authorized to commence a civil action for appropriate declaratory or injunctive relief relating to violations of this section, section 842 of this title, or 856 3 of this title."],[0,"(2) Any action under this subsection may be brought in the district court of the United States for the district in which the defendant is located or resides or is doing business."],[0,"(3) Any order or judgment issued by the court pursuant to this subsection shall be tailored to restrain violations of this section or section 842 of this title."],[0,"(4) The court shall proceed as soon as practicable to the hearing and determination of such an action. An action under this subsection is governed by the Federal Rules of Civil Procedure except that, if an indictment has been returned against the respondent, discovery is governed by the Federal Rules of Criminal Procedure."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/21/843?type=usc&year=mostrecent&link-type=html"},"head":"§843. Prohibited acts C","tname":"Food and Drugs","by":{"1":"1, 16, 26, 27","2":"12"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"1":"1"}},{"t":"case","label":"Bain v. Colbert Cnty. Nw. Ala. Health Care Auth.","cite":"233 So. 3d 945","y":2017,"court":"Ala.","url":"https://www.courtlistener.com/c/So.%203d/233/945/","by":{"2":"41"}},{"t":"case","label":"Bryan v. United States","cite":"524 U.S. 184","y":1998,"id":"1997/96-8422","sc":1,"sum":"The Court held that the term \"willfully\" in section 924(a)(1)(D) requires proof only that the defendant knew his conduct was unlawful, not that he also knew of the federal licensing requirement.","sumSrc":"Oyez","by":{"2":"25"}},{"t":"case","label":"Garnett v. Coyle","cite":"33 P.3d 114","y":2001,"court":"Wyo.","url":"https://www.courtlistener.com/c/P.3d/33/114/","by":{"2":"42"}},{"t":"case","label":"Global-Tech Appliances, Inc. v. SEB S. A.","cite":"563 U.S. 754","y":2011,"id":"2010/10-6","sc":1,"sum":"The Court ruled that induced infringement under the patent clause requires knowledge that the induced acts constitute patent infringement.","sumSrc":"Oyez","by":{"2":"35","4":"5"}},{"t":"case","label":"Seisinger v. Siebel","cite":"203 P.3d 483","y":2009,"court":"Ariz.","url":"https://www.courtlistener.com/c/P.3d/203/483/","by":{"2":"42"}},{"t":"case","label":"United States v. Behrman","cite":"258 U.S. 280","y":1922,"id":"scdb/1921-081","sc":1,"sum":"1. An exception in a statute defining an offense is met in an indictment by alleging facts sufficient to show that the defendant was not within the exception.","sumSrc":"Headnote (U.S. Reports)","by":{"2":"32","3":"13, 14","4":"18, 19"}},{"t":"case","label":"United States v. Davis","cite":"139 S. Ct. 2319","y":2019,"id":"2018/18-431","sc":1,"sum":"Title 18 U. S. C. §924(c)(3)(B), which provides enhanced penalties for using a firearm during a “crime of violence,” is unconstitutionally vague.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"39"}},{"t":"case","label":"United States v. Lane","cite":"474 U.S. 438","y":1986,"id":"1985/84-744","sc":1,"sum":"James Lane and his son Dennis, respondents in No. 84-744, were indicted on counts for, interalia,mail fraud in connection with insurance claims that were made and that insurers paid for fire damage to a restaurant and duplex that James had hired a professional arsonist to burn. The restaurant was operated by James in partnership with others. Count 1 charged James with mail fraud with regard to that fire. The duplex …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"47"}},{"t":"case","label":"United States v. Lovern","cite":"590 F.3d 1095","y":2009,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/590/1095/","by":{"2":"23, 39"}},{"t":"case","label":"United States v. Williams","cite":"553 U.S. 285","y":2008,"id":"2007/06-694","sc":1,"sum":"Held that the statute was not overly broad as written. Justice Scalia noted specifically that offers to engage in illegal transactions are categorically excluded from First Amendment protection, and he characterized the speech of an individual claiming to be in possession of child pornography in this category of unprotected speech.","sumSrc":"Oyez","by":{"2":"39"}},{"t":"case","label":"Victor v. Nebraska","cite":"511 U.S. 1","y":1994,"id":"1993/92-8894","sc":1,"op":2,"sum":"Noting that “a severe penalty is a further factor tending to suggest that . . . the usual presumption that a defendant must know the facts that make his conduct illegal should apply”.","sumSrc":"opinion","by":{"2":"44"}},{"t":"case","label":"Village of Hoffman Estates v. The Flipside, Hoffman Estates, Inc.","cite":"455 U.S. 489","y":1982,"id":"1981/80-1681","sc":1,"sum":"The ordinance is not facially overbroad or vague but is reasonably clear in its application to appellee.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"39, 40","3":"7"}},{"t":"case","label":"Warger v. Shauers","cite":"574 U.S. 40","y":2014,"id":"2014/13-517","sc":1,"sum":"The Court held that the Federal Rule of Evidence 606(b) bars the testimony of a juror regarding statements made during deliberations for the purpose of showing alleged dishonesty by a prospective juror during jury selection.","sumSrc":"Oyez","by":{"2":"45"}},{"t":"usc","label":"21 U.S.C. § 812","url":"https://www.law.cornell.edu/uscode/text/21/812","subs":["(b)(2)(B)","(b)(3)(B)","(b)(4)(B)","(b)(5)(B)"],"by":{"2":"22, 22, 22, 22"}},{"t":"usc","label":"21 U.S.C. § 824","url":"https://www.law.cornell.edu/uscode/text/21/824","subs":["(a)(4)"],"by":{"2":"21"}},{"t":"usc","label":"21 U.S.C. § 844","url":"https://www.law.cornell.edu/uscode/text/21/844","subs":["(a)"],"by":{"2":"22, 37"}},{"t":"usc","label":"21 U.S.C. § 846","url":"https://www.law.cornell.edu/uscode/text/21/846","by":{"2":"2, 7"}},{"t":"usc","label":"21 U.S.C. § 848","url":"https://www.law.cornell.edu/uscode/text/21/848","subs":["(a)","(b)","(c)"],"by":{"2":"12, 12, 12"}},{"t":"usc","label":"18 U.S.C. § 371","url":"https://www.law.cornell.edu/uscode/text/18/371","by":{"2":"7"}},{"t":"usc","label":"18 U.S.C. § 924","url":"https://www.law.cornell.edu/uscode/text/18/924","subs":["(c)(1)(2012)"],"by":{"2":"12"}},{"t":"usc","label":"18 U.S.C. § 1001","url":"https://www.law.cornell.edu/uscode/text/18/1001","subs":["(1982)"],"stext":{"head":"§1001. Statements or entries generally","paras":[[0,"(a) Except as otherwise provided in this section, whoever, in any matter within the jurisdiction of the executive, legislative, or judicial branch of the Government of the United States, knowingly and willfully—"],[1,"(1) falsifies, conceals, or covers up by any trick, scheme, or device a material fact;"],[1,"(2) makes any materially false, fictitious, or fraudulent statement or representation; or"],[1,"(3) makes or uses any false writing or document knowing the same to contain any materially false, fictitious, or fraudulent statement or entry;"],[0,"shall be fined under this title, imprisoned not more than 5 years or, if the offense involves international or domestic terrorism (as defined in section 2331), imprisoned not more than 8 years, or both. If the matter relates to an offense under chapter 109A, 109B, 110, or 117, or section 1591, then the term of imprisonment imposed under this section shall be not more than 8 years."],[0,"(b) Subsection (a) does not apply to a party to a judicial proceeding, or that party's counsel, for statements, representations, writings or documents submitted by such party or counsel to a judge or magistrate in that proceeding."],[0,"(c) With respect to any matter within the jurisdiction of the legislative branch, subsection (a) shall apply only to—"],[1,"(1) administrative matters, including a claim for payment, a matter related to the procurement of property or services, personnel or employment practices, or support services, or a document required by law, rule, or regulation to be submitted to the Congress or any office or officer within the legislative branch; or"],[1,"(2) any investigation or review, conducted pursuant to the authority of any committee, subcommittee, commission or office of the Congress, consistent with applicable rules of the House or Senate."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/1001?type=usc&year=mostrecent&link-type=html"},"head":"§1001. Statements or entries generally","tname":"Crimes and Criminal Procedure","by":{"2":"25","3":"11, 16"}},{"t":"usc","label":"18 U.S.C. § 1341","url":"https://www.law.cornell.edu/uscode/text/18/1341","by":{"2":"7"}},{"t":"usc","label":"18 U.S.C. § 1343","url":"https://www.law.cornell.edu/uscode/text/18/1343","by":{"2":"7"}},{"t":"usc","label":"18 U.S.C. § 1347","url":"https://www.law.cornell.edu/uscode/text/18/1347","by":{"2":"7"}},{"t":"usc","label":"18 U.S.C. § 1349","url":"https://www.law.cornell.edu/uscode/text/18/1349","by":{"2":"7"}},{"t":"usc","label":"18 U.S.C. § 1956","url":"https://www.law.cornell.edu/uscode/text/18/1956","subs":["(h)"],"by":{"2":"7"}},{"t":"usc","label":"18 U.S.C. § 1957","url":"https://www.law.cornell.edu/uscode/text/18/1957","by":{"2":"7, 13"}},{"t":"usc","label":"18 U.S.C. § 1962","url":"https://www.law.cornell.edu/uscode/text/18/1962","subs":["(d)"],"by":{"2":"7"}},{"t":"usc","label":"42 U.S.C. § 1320a-7b","url":"https://www.law.cornell.edu/uscode/text/42/1320a-7b","subs":["(b)(2012)"],"by":{"2":"7"}},{"t":"reg","label":"28 C.F.R. § 0.100","url":"https://www.ecfr.gov/current/title-28/section-0.100","subs":["(b)"],"by":{"2":"20"}},{"t":"rule","label":"Fed. R. Crim. P. 52","url":"https://www.law.cornell.edu/rules/frcrmp/rule_52","subs":["(a)"],"by":{"2":"47"}},{"t":"reg","label":"36 Fed. Reg. 7776","url":"https://www.govinfo.gov/link/fr/36/7776","by":{"2":"21"}},{"t":"case","label":"Carpenters v. United States","cite":"330 U.S. 395","y":1947,"id":"scdb/1946-062","sc":1,"sum":"1: Conspiracies between employers and employees to restrain interstate commerce violate § 1 of the Sherman Act. Allen Bradley Co. v. Local Union No.8,325 U.S. 797. Pp. 400,411.","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"26"}},{"t":"case","label":"Chapman v. California","cite":"386 U.S. 18","y":1967,"id":"1966/95","sc":1,"sum":"Justice Black determined that federal law must govern the application of a state harmless error rule; the Court cannot leave the formulation of rules protecting individuals from invasion by the states to those very same states.","sumSrc":"Oyez","by":{"3":"25"}},{"t":"case","label":"Connecticut v. Johnson","cite":"460 U.S. 73","y":1983,"id":"1982/81-927","sc":1,"sum":"The judgment is affirmed. 185 Conn. 163, 440 A. 2d 858, affirmed. JUSTICE BLACKMUN, joined by JUSTICE BRENNAN, JUSTICE WHITE, and JUSTICE MARSHALL, concluded that the instructional error deprived respondent of \"constitutional rights so basic to a fair trial that their infraction can never be treated as harmless error,\" Chapman v. California, 386 U. S. 18, 23. No matter how strong the prosecution's evidence, a …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"26"}},{"t":"case","label":"Kotteakos v. United States","cite":"328 U.S. 750","y":1946,"id":"scdb/1945-029","sc":1,"sum":"The rights of petitioner were substantially prejudiced, within the meaning of § 269 of the Judicial Code, and the judgment is reversed. Berger v. United States., 295 U. S. 78, distinguished. Pp. 756, 777.","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"25"}},{"t":"case","label":"Neder v. United States","cite":"527 U.S. 1","y":1999,"id":"1998/97-1985","sc":1,"sum":"The Court held 6-3 that under the harmless-error rule, which applies to a jury instruction that omits an element of an offense, the trial court's error did not render Neder's trial \"fundamentally unfair.\" Thus, the error was harmless.","sumSrc":"Oyez","by":{"3":"26","4":"7"}},{"t":"case","label":"Rose v. Clark","cite":"478 U.S. 570","y":1986,"id":"1985/84-1974","sc":1,"sum":"Respondent was charged with the murder of two persons arising from the same incident. At his trial in a Tennessee state court he defended on the ground, inter alia, that he was either insane or incapable of forming the requisite intent to kill the victims. The court instructed the jury on both first-degree murder, which requires proof of premeditation and deliberation under Tennessee law, and second-degree murder, …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"25"}},{"t":"case","label":"Skilling v. United States","cite":"561 U.S. 358","y":2010,"id":"2009/08-1394","sc":1,"sum":"The Court held that the former CEO of Enron received a fair trial before an impartial jury, and that the federal law that makes it a crime to deprive someone of a fair and honest trial only applies to bribery and kickback schemes.","sumSrc":"Oyez","by":{"3":"6"}},{"t":"case","label":"United States v. Nichols","cite":"784 F.3d 666","court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/784/666/","by":{"3":"19"}},{"t":"case","label":"United States v. Touby","cite":"500 U.S. 160","y":1991,"id":"1990/90-6282","sc":1,"sum":"The Court held that the Controlled Substances Act allows the Attorney General to delegate authority to the Drug Enforcement Agency.","sumSrc":"Oyez","by":{"3":"19"}},{"t":"case","label":"Carter v. Kentucky","cite":"450 U.S. 288","y":1981,"id":"1980/80-5060","sc":1,"sum":"Petitioner had a right to the requested instruction under the privilege against compulsory self-incrimination of the Fifth Amendment as made applicable to the States by the Fourteenth Amendment, a state trial judge having a constitutional obligation, upon proper request, to minimize the danger that the jury will give evidentiary weight to a defendant's failure to testify.","sumSrc":"Syllabus (U.S. Reports)","by":{"4":"10"}},{"t":"case","label":"Cupp v. Naughten","cite":"414 U.S. 141","y":1973,"id":"1973/72-1148","sc":1,"sum":"The instriuction cannot be considered in isolation and when viewed, as it must be, in the context of the overall charge, in which the trial court twice gave explicit instructions affirming the presumption of.innocence and declaring the State's obligation to prove guilt beyond a reasonable doubt, did not so infect the entire trial that the resulting conviction violated the requirements of the Due Process Clause of …","sumSrc":"Syllabus (U.S. Reports)","by":{"4":"10"}},{"t":"case","label":"Estelle v. McGuire","cite":"502 U.S. 62","y":1991,"id":"1991/90-1074","sc":1,"sum":"Neither the admission of the challenged evidence nor the jury instruction as to its use rises to the level of a due process violation.","sumSrc":"Syllabus (U.S. Reports)","by":{"4":"10"}},{"t":"case","label":"Green v. Bock Laundry Mach. Co.","cite":"490 U.S. 504","y":1989,"id":"1988/87-1816","sc":1,"sum":"Rule 609(a)(1) requires a judge to permit impeachment of a civil witness with evidence of prior felony convictions regardless of ensuant unfair prejudice to the witness or the party offering the testimony. Thus, the District Court did not err in allowing the jury to learn through impeaching cross-examination that Green was a convicted felon.","sumSrc":"Syllabus (U.S. Reports)","by":{"4":"17"}},{"t":"case","label":"Leary v. United States","cite":"395 U.S. 6","y":1969,"id":"1968/65","sc":1,"sum":"Petitioner, accompanied by his daughter, son, and two others, on an automobile trip from New York to Mexico, after apparent denial of entry into Mexico, drove back across the International Bridge into Texas, where a customs officer through a search discovered some marihuana in the car and on petitioner's daughter's person. Petitioner was indicted under 26 U. S. C. § 4744 (a) (2), a subsection of the Marihuana Tax …","sumSrc":"Syllabus (U.S. Reports)","by":{"4":"5"}},{"t":"case","label":"Oregon v. Kennedy","cite":"456 U.S. 667","y":1982,"id":"1981/80-1991","sc":1,"sum":"During respondent's trial for theft in an Oregon state court, the State's expert witness testified as to the value and identity of the property involved. On cross-examination, he acknowledged that he had once filed an unrelated criminal complaint against respondent, but explained that no action had been taken on his complaint. On redirect examination, the court sustained a series of objections to the prosecutor's …","sumSrc":"Syllabus (U.S. Reports)","by":{"4":"20"}},{"t":"case","label":"Richardson v. Marsh","cite":"481 U.S. 200","y":1987,"id":"1986/85-1433","sc":1,"sum":"The Court held that not only did the jury receive instructions not to consider the confession in assessing Marsh’s guilt, but also the confession was redacted so that there was no incriminating evidence regarding Marsh’s actions. Without the implication that the evidence in the confession was incriminating, Marsh’s Confrontation Clause rights were not violated.","sumSrc":"Oyez","by":{"4":"11"}},{"t":"case","label":"Taggart v. Lorenzen","cite":"139 S. Ct. 1795","y":2019,"id":"2018/18-489","sc":1,"op":1,"sum":"A creditor may be held in civil contempt for violating a bankruptcy court’s discharge order if there is no fair ground of doubt as to whether the order barred the creditor’s conduct.","sumSrc":"Holding (supremecourt.gov)","by":{"4":"18"}},{"t":"case","label":"Taylor v. Kentucky","cite":"436 U.S. 478","y":1978,"id":"1977/77-5549","sc":1,"sum":"On the facts, the trial court's refusal to give petitioner's requested instruction on the presumption of innocence resulted in a violation of his right to a fair trial as guaranteed by the Due Process Clause of the Fourteenth Amendment. Howard v. Fleming, 191 U. S. 126, distinguished.","sumSrc":"Syllabus (U.S. Reports)","by":{"4":"10"}},{"t":"case","label":"Trimarco v. Klein","cite":"56 N.Y.2d 98","y":1982,"url":"https://www.courtlistener.com/c/N.Y.2d/56/98/","by":{"4":"6"}},{"t":"case","label":"United Sav. Ass’n of Tex. v. Timbers of Inwood Forest Assocs., Ltd.","cite":"484 U.S. 365","y":1988,"id":"1987/86-1602","sc":1,"sum":"Undersecured creditors are not entitled to compensation under § 362(d)(1) for the delay caused by the automatic stay in foreclosing on their collateral.","sumSrc":"Syllabus (U.S. Reports)","by":{"4":"17"}},{"t":"case","label":"United States Nat’l Bank of Or. v. Independent Ins. Agents of Am., Inc.","cite":"508 U.S. 439","y":1993,"id":"1992/92-484","sc":1,"sum":"The Act of Sept. 7, 1916, 39 Stat. 753 (1916 Act), among other things, authorized any national bank doing business in a community with a population not exceeding 5,000 to act as the agent for any insurance company. Although early editions of the United States Code included this provision as section 92 of Title 12 (section 92), the 1952 Code and subsequent editions omitted section 92 with a note indicating that …","sumSrc":"Syllabus (U.S. Reports)","by":{"4":"16"}},{"t":"case","label":"Page(s) United States v. Hale","cite":"857 F.3d 158","y":2017,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/857/158/","by":{"4":"5"}},{"t":"case","label":"United States v. Houston","cite":"792 F.3d 663","y":2015,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/792/663/","by":{"4":"6"}},{"t":"case","label":"United States v. Jewell","cite":"532 F.2d 697","y":1976,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/532/697/","by":{"4":"5"}},{"t":"case","label":"Waddington v. Sarausad","cite":"555 U.S. 179","y":2009,"id":"2008/07-772","sc":1,"sum":"The Court found that a federal court may reject a state court's conclusion with respect to the appropriateness of the state court jury instruction, so long as the instructions were \"not only erroneous, but objectively unreasonable.\"","sumSrc":"Oyez","by":{"4":"10"}},{"t":"reg","label":"87 Fed. Reg. 7838","url":"https://www.govinfo.gov/link/fr/87/7838","by":{"4":"22"}}]};